const sorters={recent:(a,b)=>a.posted-b.posted,'price-asc':(a,b)=>a.price-b.price,'price-desc':(a,b)=>b.price-a.price,nearest:(a,b)=>a.distance-b.distance,savings:(a,b)=>(b.retail-b.price)/b.retail-(a.retail-a.price)/a.retail};
const limit=value=>{if(value===null||value==='')return Infinity;const n=Number(value);return Number.isNaN(n)||n<0?null:n;};
function filterMarketplace(params){
 const max=limit(params.get('budget')),miles=limit(params.get('distance'));if(max===null||miles===null)return [];
 const q=(params.get('q')||'').toLowerCase().trim(),platform=params.get('platform'),category=params.get('category');
 const results=marketplaceListings.filter(p=>p.price<=max&&p.distance<=miles&&(!platform||platform==='all'||p.platform===platform)&&(!category||category==='all'||p.category===category)&&(params.get('available')!=='true'||p.status==='Available')&&(params.get('portable')!=='true'||p.portable)&&`${p.name} ${p.condition} ${p.area} ${p.category}`.toLowerCase().includes(q));
 return results.sort(sorters[params.get('sort')]||sorters.recent);
}

const assets = {"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Room Edit — Find your furniture direction</title><meta name=\"description\" content=\"A considered room, within your budget. Match furniture ideas to your style and color palette.\"><style>\n:root{--ink:#232b26;--green:#315a42;--paper:#f5f4ef;--line:#dadbd3}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Arial,sans-serif;font-size:16px}button,input,select{font:inherit}button,select,input{accent-color:var(--green)}button{cursor:pointer}header{height:86px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 5vw}.brand{font-family:Georgia,serif;font-size:30px;letter-spacing:-1px}.brand span{color:#73855a}header small{font-size:13px;letter-spacing:2px;text-transform:uppercase}main{max-width:1500px;margin:auto;padding:44px 5vw}h1{font-family:Georgia,serif;font-size:clamp(36px,4vw,58px);font-weight:400;letter-spacing:-2px;margin:0 0 12px}h2{font-size:23px;font-weight:500;margin:0}.intro{margin:0 0 34px;color:#667067;line-height:1.6}.layout{display:grid;grid-template-columns:330px 1fr;gap:42px}aside{border:1px solid var(--line);background:#fff;padding:26px;height:fit-content;border-radius:4px}.field{border:0;padding:0;margin:0 0 26px;min-width:0}.label,legend{display:block;font-size:14px;font-weight:bold;margin:0 0 13px}.label span,legend span{color:#8b928b;margin-right:9px;font-size:12px}select,input[type=number]{width:100%;border:1px solid var(--line);border-radius:4px;background:#fff;padding:12px;color:var(--ink)}.vibes{display:grid;grid-template-columns:1fr 1fr;gap:8px}.choice{position:relative}.choice input{position:absolute;opacity:0}.choice label{display:block;border:1px solid var(--line);border-radius:4px;padding:11px 8px;font-size:14px;text-align:center;cursor:pointer}.choice input:checked+label{background:#eaf0e9;border-color:var(--green);color:var(--green)}.choice input:focus-visible+label{outline:3px solid #8d9bb5;outline-offset:2px}.palettes{display:flex;gap:12px}.palette{border:1px solid transparent;background:none;padding:5px;border-radius:30px;display:flex;gap:0}.palette[aria-pressed=true]{border-color:var(--ink)}.swatch{width:21px;height:29px;display:block}.swatch:first-child{border-radius:15px 0 0 15px}.swatch:last-child{border-radius:0 15px 15px 0}.palette-name{font-size:14px;color:#677066;margin-top:9px}input[type=range]{width:100%;margin:18px 0 6px}.range-labels{display:flex;justify-content:space-between;font-size:12px;color:#788077}.primary{width:100%;background:var(--green);color:white;border:0;padding:16px;border-radius:4px;font-weight:bold}.primary:hover{background:#234731}.note{font-size:12px;color:#70786e;line-height:1.6;margin:12px 0 0}.inspiration{position:relative;height:295px;overflow:hidden;border-radius:4px;background:#d8dfd5}.inspiration img{width:100%;height:100%;object-fit:cover;object-position:center 62%}.photo-label{position:absolute;bottom:17px;left:19px;background:#ffffffeb;padding:9px 12px;border-radius:3px;font-size:12px}.photo-credit{position:absolute;bottom:18px;right:15px;color:white;background:#0007;padding:5px;font-size:12px}.results-head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:26px 0 12px}.eyebrow{font-size:11px;letter-spacing:1.8px;text-transform:uppercase;color:#687263;margin:0 0 7px}.badge{background:#e4ebdf;color:#33523a;padding:8px 10px;white-space:nowrap;border-radius:20px;font-size:12px}.description{color:#6a7169;line-height:1.6;font-size:14px;margin:0 0 22px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:13px}.card{padding:20px;background:white;border:1px solid var(--line);border-radius:4px}.card-top{display:flex;justify-content:space-between;font-size:12px;color:#6f796f;margin-bottom:18px}.material{width:30px;height:14px;border-radius:20px}.card h3{font-family:Georgia,serif;font-size:21px;font-weight:400;margin:0 0 8px}.card p{font-size:14px;line-height:1.5;color:#6c746a;min-height:42px;margin:0 0 15px}.card-bottom{display:flex;justify-content:space-between;align-items:center}.price{font-size:20px}.swap{border:0;background:none;color:var(--green);padding:8px 0;font-size:13px;text-decoration:underline;text-underline-offset:3px}.summary{margin-top:17px;padding:20px 0;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:18px}.summary strong{font-size:24px;font-weight:500}.summary p{font-size:13px;color:#677066;margin:6px 0}.error{color:#aa322d;font-size:14px}.footer{margin-top:45px;padding-top:22px;border-top:1px solid var(--line);font-size:12px;color:#6c756a;display:flex;justify-content:space-between}.hide{display:none}@media(max-width:850px){.layout{grid-template-columns:280px 1fr;gap:22px}.cards{grid-template-columns:1fr}main{padding:30px 4vw}aside{padding:20px}.inspiration{height:240px}}@media(max-width:640px){header{height:70px}header small{font-size:10px;letter-spacing:1px}.layout{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}.card{padding:15px}.card h3{font-size:19px}.inspiration{height:260px}.results-head{align-items:flex-start}.badge{white-space:normal}h1{letter-spacing:-1px}.summary{align-items:flex-start}.footer{gap:20px}}@media(prefers-reduced-motion:no-preference){button{transition:background .18s} .card{animation:enter .3s ease}@keyframes enter{from{opacity:.4;transform:translateY(4px)}to{opacity:1;transform:none}}}\n</style><link rel=\"stylesheet\" href=\"photo.css\"><link rel=\"stylesheet\" href=\"room-tools.css\"><link rel=\"stylesheet\" href=\"marketplace.css\"><script type=\"text/javascript\">\n    (function(c,l,a,r,i,t,y){\n        c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};\n        t=l.createElement(r);t.async=1;t.src=\"https://www.clarity.ms/tag/\"+i;\n        y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);\n    })(window, document, \"clarity\", \"script\", \"zendxpx6at\");\n</script>\n</head><body><header><div class=\"brand\">room<span>edit</span><span style=\"font-size:18px\"> ◒</span></div><small>A space that feels like you</small></header><main><nav class=\"mode-tabs\" aria-label=\"Furniture tools\"><button type=\"button\" id=\"photo-tab\" aria-pressed=\"true\">Shop a photo</button><button type=\"button\" id=\"planner-tab\" aria-pressed=\"false\">Plan by style</button></nav><section id=\"photo-mode\"><div class=\"photo-intro\"><p class=\"eyebrow\">FROM INSPO TO IN YOUR ROOM</p><h1>Love the look? Find the pieces.</h1><p class=\"intro\">Upload a room or furniture photo. Find similar pieces you can shop online.</p></div><div class=\"layout\"><aside><form id=\"photo-form\"><label class=\"upload-zone\" id=\"drop-zone\" for=\"inspo-file\"><span class=\"upload-icon\" aria-hidden=\"true\">＋</span><strong>Add your inspiration</strong><span>Choose a photo or drop it here</span><small>JPG, PNG or WebP · up to 10 MB</small><input type=\"file\" id=\"inspo-file\" accept=\"image/jpeg,image/png,image/webp\"></label><div id=\"photo-preview\" hidden><img id=\"uploaded-preview\" alt=\"Your furniture inspiration\"><button type=\"button\" id=\"remove-photo\" class=\"swap\">Remove photo</button></div><div class=\"field\"><label class=\"label\" for=\"photo-budget\">Maximum price per piece · USD</label><input id=\"photo-budget\" type=\"number\" min=\"10\" max=\"20000\" step=\"1\" value=\"2500\" required></div><div class=\"field\"><label class=\"label\" for=\"photo-category\">Find similar</label><select id=\"photo-category\"><option value=\"all\">Any furniture in the photo</option><option value=\"sofa\">Sofas</option><option value=\"chair\">Accent chairs</option><option value=\"table\">Coffee & side tables</option><option value=\"bed\">Beds</option><option value=\"desk\">Desks</option><option value=\"storage\">Storage</option><option value=\"rug\">Rugs</option><option value=\"lamp\">Lighting</option></select></div><div class=\"field\"><label class=\"label\" for=\"photo-retailer\">Shop from</label><select id=\"photo-retailer\"><option value=\"all\">All retailers</option></select></div><button class=\"primary\" id=\"match-button\" type=\"submit\" disabled>Find similar pieces ↗</button><button class=\"secondary\" id=\"cancel-match\" type=\"button\" hidden>Cancel</button><p id=\"match-status\" role=\"status\" class=\"note\">Your photo stays on your device. First use downloads the image-matching model and may take a minute.</p><progress id=\"match-progress\" max=\"100\" hidden aria-label=\"Loading photo matching\"></progress><p id=\"photo-error\" class=\"error\" role=\"alert\"></p></form></aside><section aria-label=\"Furniture matches\"><div id=\"photo-results\" aria-live=\"polite\"><div class=\"photo-empty\"><span class=\"eyebrow\">YOUR NEXT FIND STARTS HERE</span><h2>A room screenshot.<br>A chair you love.<br>A whole new direction.</h2><p>Choose an inspiration photo to see similar products from our curated US catalog from IKEA, Article, Castlery and Target.</p><p class=\"note\">Visual suggestions, not guaranteed exact matches. Retailer prices and stock can change.</p></div></div></section></div></section><section id=\"planner-mode\" hidden><h1>Your taste. Your space. Your budget.</h1><p class=\"intro\">A few preferences. A considered furniture plan.</p><div class=\"layout\"><aside><form id=\"preferences\"><div class=\"field\"><label class=\"label\" for=\"room\"><span>01</span>Choose your room</label><select id=\"room\"><option>Living room</option><option>Bedroom</option><option>Home office</option></select></div><fieldset class=\"field\"><legend><span>02</span>Set the vibe</legend><div class=\"vibes\" id=\"vibes\"></div></fieldset><div class=\"field\"><p class=\"label\"><span>03</span>Pick a color story</p><div class=\"palettes\" id=\"palettes\" role=\"group\" aria-label=\"Color palette\"></div><div class=\"palette-name\" id=\"palette-name\"></div></div><div class=\"field\"><label class=\"label\" for=\"budget\"><span>04</span>Your total budget · USD</label><input type=\"number\" id=\"budget\" min=\"300\" max=\"20000\" step=\"50\" value=\"2500\" required><input id=\"range\" type=\"range\" min=\"300\" max=\"20000\" step=\"50\" value=\"2500\" aria-label=\"Total budget\"><div class=\"range-labels\"><span>$300</span><span>$20,000</span></div></div><button class=\"primary\" type=\"submit\">Find my furniture <span aria-hidden=\"true\">↗</span></button><p class=\"note\">Furniture ideas + spending targets.<br>Retailer inventory and prices aren’t live.</p></form></aside><section><div class=\"inspiration\"><img src=\"https://images.unsplash.com/photo-1738168279272-c08d6dd22002?auto=format&fit=crop&w=1800&q=85\" alt=\"Modern living room with a green sofa and warm wood furniture\"><span class=\"photo-label\">THE MOODBOARD · Living room inspiration</span><a class=\"photo-credit\" href=\"https://unsplash.com/photos/a-living-room-with-a-couch-a-table-and-chairs-vYlmRFIsCIk\" target=\"_blank\" rel=\"noopener\">Photo: Prydumano Design</a></div><div id=\"results\" aria-live=\"polite\"></div></section></div></section><footer class=\"footer\"><span>roomedit · A little more you.</span><span>Measure your space. Confirm price and delivery with the retailer.</span></footer></main><script src=\"app.js\"></script><script type=\"module\" src=\"photo.js\"></script><script type=\"module\" src=\"room-tools.js\"></script><script type=\"module\" src=\"marketplace.js\"></script></body></html>\n"},"/app.js":{"type":"text/javascript; charset=utf-8","body":"const styles=['Organic modern','Mid-century','Minimalist','Industrial','Coastal','Eclectic'];\nconst palettes=[{name:'Earth & olive',colors:['#52634b','#b79469','#eee5d3'],finish:'walnut',fabric:'olive'},{name:'Warm neutrals',colors:['#c3ab8d','#e4d7c6','#8b6b54'],finish:'oak',fabric:'oatmeal'},{name:'Monochrome',colors:['#303430','#a4a6a1','#e8e9e4'],finish:'black-stained wood',fabric:'charcoal'},{name:'Coastal blues',colors:['#526d83','#a9bdc6','#ede3cc'],finish:'light oak',fabric:'slate blue'}];\nlet palette=0,current,variants=[0,0,0,0];const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);\ndocument.querySelector('#vibes').innerHTML=styles.map((s,i)=>`<div class=\"choice\"><input type=\"radio\" name=\"vibe\" id=\"v${i}\" value=\"${s}\" ${i===0?'checked':''}><label for=\"v${i}\">${s}</label></div>`).join('');\nfunction palettesRender(){document.querySelector('#palettes').innerHTML=palettes.map((p,i)=>`<button type=\"button\" class=\"palette\" aria-label=\"${p.name}\" aria-pressed=\"${i===palette}\" data-palette=\"${i}\">${p.colors.map(c=>`<span class=\"swatch\" style=\"background:${c}\"></span>`).join('')}</button>`).join('');document.querySelector('#palette-name').textContent=palettes[palette].name;}palettesRender();\ndocument.querySelector('#palettes').addEventListener('click',e=>{const b=e.target.closest('button');if(b){palette=Number(b.dataset.palette);palettesRender();}});\nconst budget=document.querySelector('#budget'),range=document.querySelector('#range');budget.addEventListener('input',()=>range.value=budget.value);range.addEventListener('input',()=>budget.value=range.value);\nconst rooms={'Living room':[['Sofa','Low-profile sofa','Rounded loveseat'],['Coffee table','Oval coffee table','Nesting tables'],['Accent chair','Lounge chair','Sling chair'],['Rug','Textured area rug','Flatweave rug']],'Bedroom':[['Bed frame','Upholstered bed frame','Platform bed frame'],['Nightstands','Pair of nightstands','Pair of bedside tables'],['Dresser','Low dresser','Tall chest'],['Rug','Soft bedside rug','Flatweave area rug']],'Home office':[['Desk','Writing desk','Compact work desk'],['Chair','Adjustable task chair','Ergonomic office chair'],['Storage','Low storage cabinet','Open bookcase'],['Lighting','Adjustable desk lamp','Task floor lamp']]};\nconst details={'Organic modern':['Soft curves','Rounded edges','Sculptural silhouette','Natural texture'],'Mid-century':['Tapered legs','Clean lines','Retro profile','Geometric detail'],'Minimalist':['Simple profile','Slim silhouette','Understated shape','Quiet texture'],'Industrial':['Structured shape','Metal details','Exposed frame','Durable texture'],'Coastal':['Relaxed shape','Airy silhouette','Open details','Woven texture'],'Eclectic':['Expressive shape','Playful proportions','Statement profile','Patterned texture']};\nfunction render(){const {room,vibe,total,p}=current;const weights=[.43,.19,.18,.10];const allocations=weights.map(w=>Math.floor(total*w/5)*5);const spent=allocations.reduce((a,b)=>a+b,0);document.querySelector('#results').innerHTML=`<div class=\"results-head\"><div><p class=\"eyebrow\">Your personal edit · ${room}</p><h2>${vibe}, ${p.name.toLowerCase()}</h2></div><span class=\"badge\">Within your ${money(total)} budget</span></div><p class=\"description\">${p.fabric[0].toUpperCase()+p.fabric.slice(1)} tones, ${p.finish}, and ${details[vibe][3].toLowerCase()}. Four pieces that work together, with room left for the finishing touches.</p><div class=\"cards\">${rooms[room].map((r,i)=>`<article class=\"card\"><div class=\"card-top\"><span>0${i+1} / ${r[0].toUpperCase()}</span><span class=\"material\" style=\"background:${p.colors[i%3]}\"></span></div><h3>${r[1+variants[i]]}</h3><p>${details[vibe][i]}. ${i===0||i===3?p.fabric+' tones':p.finish+' finish'} to tie the room together.</p><div class=\"card-bottom\"><span class=\"price\">${money(allocations[i])}<span style=\"font-size:12px;color:#727a70\"> target</span></span><button class=\"swap\" data-swap=\"${i}\" aria-label=\"Swap ${r[0]} idea\">Swap idea ↻</button></div></article>`).join('')}</div><div class=\"summary\"><div><span style=\"font-size:14px\">Furniture spending target</span><p>${money(total-spent)} reserved for delivery, tax & extras</p></div><strong>${money(spent)}</strong></div><p class=\"note\">These are suggested furniture types and budget allocations, not product listings or price quotes.${room==='Bedroom'?' Mattress and bedding are not included.':''} ${total<800?'At this budget, prioritize secondhand pieces and check local availability.':''} The inspiration photo is illustrative and does not change with your selections.</p>`;}\ndocument.querySelector('#results').addEventListener('click',e=>{const b=e.target.closest('[data-swap]');if(b){const i=Number(b.dataset.swap);variants[i]=1-variants[i];render();document.querySelector(`[data-swap=\"${i}\"]`).focus();}});\nfunction generate(){current={room:document.querySelector('#room').value,vibe:document.querySelector('input[name=vibe]:checked').value,total:Number(budget.value),p:palettes[palette]};variants=[0,0,0,0];render();}\ndocument.querySelector('#preferences').addEventListener('submit',e=>{e.preventDefault();generate();if(innerWidth<641)document.querySelector('#results').scrollIntoView({behavior:'smooth',block:'start'});});generate();\n"},"/photo.js":{"type":"text/javascript; charset=utf-8","body":"import {catalog,checkedDate,filterMatches,retailers} from './catalog.js';\nconst $=s=>document.querySelector(s);\n$('#photo-retailer').insertAdjacentHTML('beforeend',retailers.map(r=>`<option value=\"${r}\">${r}</option>`).join(''));\n$('#inspo-file').multiple=true;$('#drop-zone').querySelector('strong').textContent='Add up to 5 inspiration photos';$('#drop-zone').querySelector('small').textContent='JPG, PNG or WebP · 10 MB each';$('#photo-preview').insertAdjacentHTML('beforeend','<div class=\"inspo-thumbs\" id=\"inspo-thumbs\"></div>');\nconst emptyMarkup=$('#photo-results').innerHTML;\nconst money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);\nlet photos=[],preferences={},photo=null,previewUrl=null,worker=null,timer=null,busy=false,scores=null,readVersion=0;\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nfunction switchMode(mode){for(const m of ['photo','planner']){$(`#${m}-mode`).hidden=m!==mode;$(`#${m}-tab`).setAttribute('aria-pressed',String(m===mode));}}\n$('#photo-tab').onclick=()=>switchMode('photo');$('#planner-tab').onclick=()=>switchMode('planner');\nfunction stop(message){clearTimeout(timer);worker?.terminate();worker=null;setBusy(false);$('#match-status').textContent=message;}\nfunction setBusy(value){busy=value;$('#match-button').disabled=value||!photo;$('#match-button').textContent=value?'Finding your pieces…':'Find similar pieces ↗';$('#cancel-match').hidden=!value;$('#match-progress').hidden=!value;$('#photo-budget').disabled=value;$('#photo-category').disabled=value;$('#photo-retailer').disabled=value;$('#inspo-file').disabled=value;$('#remove-photo').disabled=value;if(value)$('#match-progress').removeAttribute('value');}\nfunction clearResults(){scores=null;$('#photo-results').innerHTML=emptyMarkup;}\nfunction clearPhoto(){readVersion++;stop('Your photo stays on your device. First use downloads the image-matching model and may take a minute.');photo=null;photos=[];$('#inspo-thumbs').innerHTML='';$('#inspo-file').value='';$('#photo-preview').hidden=true;$('#uploaded-preview').removeAttribute('src');$('#match-button').disabled=true;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=null;$('#photo-error').textContent='';clearResults();}\nasync function loadPhotos(files){if(busy)return;clearPhoto();const chosen=Array.from(files||[]);if(chosen.length>5){$('#photo-error').textContent='Choose up to five photos.';return;}const version=readVersion;const loaded=[];try{for(const file of chosen){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw Error('Use JPG, PNG or WebP images under 10 MB each.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(version!==readVersion)return;if(!img.naturalWidth||img.naturalWidth*img.naturalHeight>80000000)throw Error('Choose a smaller image.');const scale=Math.min(1,1024/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);loaded.push(c.toDataURL('image/jpeg',.9));}finally{URL.revokeObjectURL(url);}}if(version!==readVersion)return;photos=loaded;photo=photos[0];if(!photo)return;$('#uploaded-preview').src=photo;$('#photo-preview').hidden=false;$('#inspo-thumbs').innerHTML=photos.map((src,i)=>`<img src=\"${src}\" alt=\"Inspiration ${i+1}\">`).join('');$('#match-button').disabled=false;$('#match-status').textContent=photos.length+' photos ready. Their match scores will be combined.';}catch(error){$('#photo-error').textContent=error.message||'Could not read those photos.';}}\n$('#inspo-file').addEventListener('change',e=>loadPhotos(e.target.files));$('#remove-photo').onclick=clearPhoto;\nfor(const event of ['dragenter','dragover'])$('#drop-zone').addEventListener(event,e=>{e.preventDefault();if(!busy)$('#drop-zone').classList.add('dragging');});\nfor(const event of ['dragleave','drop'])$('#drop-zone').addEventListener(event,e=>{e.preventDefault();$('#drop-zone').classList.remove('dragging');if(event==='drop'&&!busy)loadPhotos(e.dataTransfer.files);});\n$('#cancel-match').onclick=()=>{stop('Matching cancelled. Your photo is ready when you are.');clearResults();};\n$('#photo-results').addEventListener('error',e=>{if(e.target.matches('.product-image')){e.target.hidden=true;e.target.nextElementSibling.hidden=false;}},true);\nfunction showResults(){if(!scores)return;const budget=Number($('#photo-budget').value),category=$('#photo-category').value;const found=filterMatches(scores.map(s=>({...s,score:s.score*(preferences[s.label]===1?1.5:preferences[s.label]===-1?.2:1)})),{budget,category,retailer:$('#photo-retailer').value});if(!found.length){$('#photo-results').innerHTML='<div class=\"photo-empty\"><p class=\"eyebrow\">NO CLOSE MATCHES IN THIS CATALOG</p><h2>Let’s try a different angle.</h2><p>No close catalog matches fit these filters. Try another retailer or furniture category, a higher per-piece budget, or a photo focused on one item.</p><p class=\"note\">We won’t fill the results with unrelated products.</p></div>';return;}\n $('#photo-results').innerHTML=`<div class=\"match-head\"><div><p class=\"eyebrow\">YOUR PHOTO → REAL PIECES</p><h2>Similar pieces to shop</h2></div><span class=\"badge\">${found.length} suggestions</span></div><p class=\"results-note\">Ranked by visual similarity to product descriptions in our ${catalog.length}-piece catalog across ${retailers.length} US retailers. These are alternatives, not a room bundle or guaranteed exact matches.</p><div class=\"match-grid\">${found.map(({product:p},i)=>`<article class=\"product\"><a class=\"product-photo-link\" href=\"${esc(p.url)}\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"View ${esc(p.name)} ${esc(p.type)} at ${esc(p.retailer)}\"><img class=\"product-image\" src=\"${esc(p.image)}\" alt=\"${esc(p.name)} ${esc(p.type)} — ${esc(p.detail)}\" width=\"640\" height=\"480\" loading=\"lazy\" decoding=\"async\"><span class=\"image-unavailable\" hidden>Photo unavailable · View at ${esc(p.retailer)} ↗</span></a><div class=\"product-body\"><div class=\"card-top\"><span>${esc(p.retailer)} · ${esc(p.type)}</span><span>#${i+1}</span></div><div class=\"product-swatches\" aria-label=\"Approximate product colors\">${p.swatches.map(c=>`<span style=\"background:${c}\"></span>`).join('')}</div><h3>${esc(p.name)}</h3><p>${esc(p.detail)}</p><p class=\"note\">Checked ${esc(p.checkedDate)}</p>${p.note?`<p class=\"note\">${esc(p.note)}</p>`:''}<div class=\"product-bottom\"><div><span class=\"product-price\">${money(p.price)}</span><div class=\"note\">Listed price · USD</div></div><a class=\"shop-link\" href=\"${esc(p.url)}\" target=\"_blank\" rel=\"noopener noreferrer\">View at ${esc(p.retailer)} ↗</a></div><div class=\"feedback-actions\"><button data-save=\"${esc(p.id)}\">Save to room board</button><button data-feedback=\"${esc(p.id)}\" data-value=\"1\" aria-pressed=\"${preferences[p.caption]===1}\">More like this</button><button data-feedback=\"${esc(p.id)}\" data-value=\"-1\" aria-pressed=\"${preferences[p.caption]===-1}\">Less like this</button></div></div></article>`).join('')}</div><p class=\"results-note\">Product listings checked ${checkedDate}. Prices are not live; tax and delivery are extra. Confirm current price, dimensions and availability on the retailer’s page. Color swatches are approximate.</p>`;\n}\nfor(const id of ['photo-budget','photo-category','photo-retailer'])$('#'+id).addEventListener('change',()=>{if($('#photo-form').checkValidity())showResults();});\n$('#photo-form').addEventListener('submit',e=>{e.preventDefault();if(!photo||busy)return;$('#photo-error').textContent='';if(scores){showResults();return;}setBusy(true);$('#photo-results').innerHTML='<div class=\"photo-empty\"><p class=\"eyebrow\">FINDING YOUR NEXT PIECE</p><h2>Taking a closer look.</h2><p>Comparing the shapes, materials and colors in your inspiration to real furniture listings.</p></div>';\n try{if(!worker)worker=new Worker(new URL('./matcher-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.type==='status'||data.type==='progress'){$('#match-status').textContent=data.text;if(data.type==='progress')$('#match-progress').value=data.value;else $('#match-progress').removeAttribute('value');return;}clearTimeout(timer);setBusy(false);if(data.type==='result'){scores=data.scores;showResults();$('#match-status').textContent='Done. Adjust price or category to refine your matches.';if(innerWidth<641)$('#photo-results').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}else if(data.type==='unrecognized'){$('#match-status').textContent='Try a furniture photo.';$('#photo-results').innerHTML='<div class=\"photo-empty\"><h2>Try a clearer furniture photo.</h2><p>We couldn’t confidently recognize furniture in this image. Try a room photo or a close-up of a furniture piece.</p></div>';}else{stop('Photo matching is unavailable right now.');$('#photo-error').textContent=data.message;clearResults();}};worker.onerror=()=>{stop('Photo matching is unavailable right now.');$('#photo-error').textContent='The image matcher could not start. Check your connection and try again. The style planner still works.';clearResults();};timer=setTimeout(()=>{stop('Matching took too long.');$('#photo-error').textContent='The model download or analysis timed out. Try again on a faster connection; downloaded files may already be cached.';clearResults();},180000);worker.postMessage({images:photos,labels:catalog.map(p=>p.caption)});}catch{stop('Photo matching is unavailable in this browser.');$('#photo-error').textContent='Try an up-to-date browser with WebAssembly support.';clearResults();}\n});\nwindow.addEventListener('pagehide',()=>{worker?.terminate();if(previewUrl)URL.revokeObjectURL(previewUrl);});\n\n$('#photo-results').addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.save){window.dispatchEvent(new CustomEvent('roomedit-save',{detail:button.dataset.save}));button.textContent='Saved to board';button.disabled=true;}if(button.dataset.feedback){const p=catalog.find(p=>p.id===button.dataset.feedback);preferences[p.caption]=Number(button.dataset.value);showResults();$('#match-status').textContent='Ranking adjusted for this session. Your feedback changes this product’s priority.';}});\n"},"/photo.css":{"type":"text/css; charset=utf-8","body":"[hidden]{display:none!important}.mode-tabs{display:flex;gap:6px;margin-bottom:32px;border-bottom:1px solid var(--line)}.mode-tabs button{background:none;border:0;border-bottom:3px solid transparent;padding:12px 18px;color:#647064}.mode-tabs button[aria-pressed=true]{border-color:var(--green);color:var(--green);font-weight:700}.upload-zone{display:flex;position:relative;flex-direction:column;gap:9px;align-items:center;text-align:center;border:1px dashed #899c84;padding:25px 12px;border-radius:5px;cursor:pointer;background:#f1f5ee;margin-bottom:20px}.upload-zone:focus-within{outline:3px solid #8197b0}.upload-zone.dragging{background:#dce8d4;border:2px solid #315a42}.upload-zone span{font-size:14px;color:#5c6959}.upload-zone .upload-icon{font-size:30px;line-height:1}.upload-zone small{font-size:12px;color:#697865}.upload-zone input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%}#uploaded-preview{width:100%;max-height:250px;object-fit:contain;border-radius:4px;background:#eef0ea}#photo-preview{margin-bottom:22px}button:disabled{opacity:.5;cursor:not-allowed}.secondary{background:white;border:1px solid var(--line);padding:10px;width:100%;margin-top:10px;border-radius:4px}.photo-empty{background:#e8eee3;min-height:470px;display:flex;flex-direction:column;justify-content:center;padding:50px;border-radius:5px}.photo-empty h2{font-family:Georgia,serif;font-size:clamp(32px,3vw,46px);line-height:1.25;margin:20px 0;letter-spacing:-1px}.photo-empty p{max-width:420px;color:#57634f;line-height:1.7}.match-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.product{background:#fff;border:1px solid var(--line);border-radius:5px;overflow:hidden;display:flex;flex-direction:column}.product-image{aspect-ratio:4/3;object-fit:contain;width:100%;background:#f9faf7}.product-body{padding:20px;display:flex;flex-direction:column;flex:1}.product h3{font-family:Georgia,serif;font-size:24px;margin:7px 0 9px;font-weight:400}.product p{font-size:14px;line-height:1.5;color:#64705c;margin:0 0 16px}.product .product-bottom{margin-top:auto;display:flex;justify-content:space-between;align-items:center;gap:10px}.shop-link{background:var(--green);color:#fff;text-decoration:none;padding:10px 13px;border-radius:4px;font-size:14px}.product-price{font-size:20px}.results-note{font-size:13px;line-height:1.6;color:#677063;margin:8px 0 23px}.match-head{margin-bottom:10px;display:flex;justify-content:space-between;gap:15px;align-items:center}.match-head h2{font-family:Georgia,serif;font-size:30px}progress{width:100%;margin-top:12px;height:8px}#photo-error:empty{display:none}.photo-intro .intro{margin-bottom:30px}.image-unavailable{height:150px;background:#ecf0e7;display:grid;place-items:center;color:#677063;font-size:14px}@media(max-width:640px){.photo-empty{min-height:300px;padding:30px}.match-grid{grid-template-columns:1fr 1fr}.product-body{padding:13px}.product .product-bottom{align-items:flex-start;flex-direction:column}.product h3{font-size:20px}.photo-intro h1{font-size:38px}}@media(max-width:380px){.match-grid{grid-template-columns:1fr}}\n.product-swatches{display:flex;gap:6px;margin-bottom:10px}.product-swatches span{width:40px;height:12px;border-radius:8px;border:1px solid #0001}\n.product-photo-link{display:block;background:#fff;overflow:hidden;text-decoration:none;color:var(--green)}.product-photo-link:focus-visible{outline:3px solid var(--green);outline-offset:-3px}.product-photo-link .product-image{display:block;aspect-ratio:4/3;height:auto;padding:18px;object-fit:contain;background:white;border-bottom:1px solid var(--line)}.product-photo-link .image-unavailable{aspect-ratio:4/3;height:auto;padding:20px;text-align:center}.product-photo-link:hover .product-image{transform:scale(1.025)}@media(prefers-reduced-motion:no-preference){.product-image{transition:transform .2s ease}}\n"},"/catalog.js":{"type":"text/javascript; charset=utf-8","body":"// Product pages and US list prices checked September 25, 2026.\n// Stock, delivery and future prices must be confirmed with the retailer.\nexport const checkedDate = 'September 25–27, 2026';\nexport const catalog = [\n {id:'morabo',name:'MORABO',type:'Sofa',category:'sofa',price:799,detail:'Gunnared light green · wooden legs',caption:'a light green mid-century modern upholstered sofa with tufted cushions and exposed wooden legs',url:'https://www.ikea.com/us/en/p/morabo-sofa-gunnared-light-green-wood-s09318339/',swatches:['#99a28d','#bc9570']},\n {id:'kivik',name:'KIVIK',type:'Sofa',category:'sofa',price:899,detail:'Gunnared light green · low, wide arms',caption:'a sage green modern fabric sofa with wide low square armrests and deep cushions',url:'https://www.ikea.com/us/en/p/kivik-sofa-gunnared-light-green-s19499706/',swatches:['#a7b19f','#c9ccc2']},\n {id:'uppland',name:'UPPLAND',type:'Loveseat',category:'sofa',price:799,detail:'Blekinge white · rolled arms and slipcover',caption:'a white traditional slipcovered loveseat sofa with rounded rolled arms and soft cushions',url:'https://www.ikea.com/us/en/p/uppland-loveseat-blekinge-white-s69384114/',swatches:['#edede8','#d9d7cc']},\n {id:'poang-walnut',name:'POÄNG',type:'Armchair',category:'chair',price:149,detail:'Walnut effect · Knisa light beige cushion',caption:'a beige upholstered bentwood armchair with a curved dark walnut colored wooden frame',url:'https://www.ikea.com/us/en/p/poaeng-armchair-walnut-effect-knisa-light-beige-s09625343/',swatches:['#cdbfa6','#6f4c34']},\n {id:'poang-birch',name:'POÄNG',type:'Armchair',category:'chair',price:249,detail:'Birch veneer · Gunnared beige cushion',caption:'a light beige cushioned Scandinavian armchair with a curved pale birch wooden frame',url:'https://www.ikea.com/us/en/p/poaeng-armchair-birch-veneer-gunnared-beige-s69501981/',swatches:['#c9bba5','#dbbd8d']},\n {id:'stockholm',name:'STOCKHOLM',type:'Coffee table',category:'table',price:449.99,detail:'Walnut veneer · oval top · 70⅞ × 23¼ in',caption:'a mid-century modern oval brown walnut wood coffee table with tapered legs and a lower shelf',url:'https://www.ikea.com/us/en/p/stockholm-coffee-table-walnut-veneer-70239710/',swatches:['#875d3e','#62452d']},\n {id:'lack',name:'LACK',type:'Coffee table',category:'table',price:29.99,detail:'Black-brown · 35⅜ × 21⅝ in',caption:'a dark brown black minimalist rectangular coffee table with square legs and a lower shelf',url:'https://www.ikea.com/us/en/p/lack-coffee-table-black-brown-40104294/',swatches:['#302821','#44372b']},\n {id:'hemnes',name:'HEMNES',type:'Nightstand',category:'table',price:129.99,detail:'Black-brown · 18⅛ × 13¾ in',caption:'a traditional dark brown black wooden bedside nightstand table with a drawer and lower shelf',url:'https://www.ikea.com/us/en/p/hemnes-nightstand-black-brown-90121234/',swatches:['#332a22','#69513b']},\n {id:'tonstad',name:'TONSTAD',type:'Queen bed frame',category:'bed',price:449,detail:'Brown stained oak veneer · Luröy slats included',note:'Mattress and bedding sold separately.',caption:'a brown oak wooden queen bed frame with a solid rectangular headboard and rounded corners',url:'https://www.ikea.com/us/en/p/tonstad-bed-frame-brown-stained-oak-veneer-luroey-s39577699/',swatches:['#916946','#a17d55']},\n {id:'micke',name:'MICKE',type:'Desk',category:'desk',price:109.99,detail:'White · 41⅜ × 19⅝ in',caption:'a modern minimalist white writing computer desk with a drawer and side storage cabinet',url:'https://www.ikea.com/us/en/p/micke-desk-white-80213074/',swatches:['#eeeee9','#d6d8d3']},\n {id:'kallax',name:'KALLAX',type:'Shelf unit',category:'storage',price:49.99,detail:'White · 30⅛ × 30⅛ in',caption:'a white minimalist square open cube bookcase shelving storage unit with four compartments',url:'https://www.ikea.com/us/en/p/kallax-shelf-unit-white-20631639/',swatches:['#eeeee9','#deded8']},\n {id:'tiphede',name:'TIPHEDE',type:'Flatwoven rug',category:'rug',price:39.99,detail:'Natural/black · 7 ft 3 in × 9 ft 2 in',note:'Anti-slip underlay sold separately.',caption:'a natural beige and black flatwoven rectangular cotton area rug with a subtle woven texture',url:'https://www.ikea.com/us/en/p/tiphede-rug-flatwoven-natural-black-40559166/',swatches:['#b8ab8d','#4e4941']},\n {id:'ranarp',name:'RANARP',type:'Floor / reading lamp',category:'lamp',price:69.99,detail:'Black · adjustable arm and shade',note:'Light bulb sold separately.',caption:'a black metal industrial adjustable floor reading lamp with brass accents and a cone shaped shade',url:'https://www.ikea.com/us/en/p/ranarp-floor-reading-lamp-black-00331383/',swatches:['#282925','#b89954']}\n];\ncatalog.push(...[{\"id\": \"article-sven-sofa\", \"retailer\": \"Article\", \"name\": \"Sven 88″\", \"type\": \"Tufted sofa\", \"category\": \"sofa\", \"price\": 1299, \"detail\": \"Fir Green · tufted bench seat and wood legs\", \"caption\": \"a fir green mid-century fabric sofa with a tufted bench cushion round bolster pillows and tapered wooden legs\", \"url\": \"https://www.article.com/product/27068/sven-88-tufted-sofa-fir-green\", \"swatches\": [\"#576a54\", \"#80603e\"], \"checkedDate\": \"September 27, 2026\"}, {\"id\": \"article-sven-loveseat\", \"retailer\": \"Article\", \"name\": \"Sven 72″\", \"type\": \"Tufted loveseat\", \"category\": \"sofa\", \"price\": 1099, \"detail\": \"Fir Green · compact tufted loveseat\", \"caption\": \"a compact green fabric two seat loveseat with tufted seat bolster pillows and tapered wood legs\", \"url\": \"https://www.article.com/product/27066/sven-72-tufted-loveseat-fir-green\", \"swatches\": [\"#576a54\", \"#80603e\"], \"checkedDate\": \"September 27, 2026\"}, {\"id\": \"castlery-harper-lift\", \"retailer\": \"Castlery\", \"name\": \"Harper Lift-Top\", \"type\": \"Coffee table\", \"category\": \"table\", \"price\": 899, \"detail\": \"Chestnut · lift-top and hidden storage\", \"caption\": \"a brown chestnut wood coffee table with rounded corners tambour ribbed sides and a lift top with hidden storage\", \"url\": \"https://www.castlery.com/us/products/harper-lift-top-coffee-table\", \"swatches\": [\"#865531\", \"#b68a60\"], \"checkedDate\": \"September 27, 2026\"}, {\"id\": \"castlery-harper-marble\", \"retailer\": \"Castlery\", \"name\": \"Harper Marble\", \"type\": \"Rectangular coffee table\", \"category\": \"table\", \"price\": 899, \"detail\": \"Chestnut base · Carrara marble top\", \"caption\": \"a rectangular white Carrara marble coffee table with rounded corners and a ribbed brown wooden base\", \"url\": \"https://www.castlery.com/us/products/harper-marble-rectangular-coffee-table\", \"swatches\": [\"#e8e6de\", \"#865531\"], \"checkedDate\": \"September 27, 2026\"}, {\"id\": \"target-square-chair\", \"retailer\": \"Target\", \"name\": \"Threshold Square Back\", \"type\": \"Accent armchair\", \"category\": \"chair\", \"price\": 304, \"detail\": \"Black bouclé · wooden frame\", \"note\": \"Sale price when checked; regular price $380.\", \"caption\": \"a black boucle upholstered square back accent armchair with an exposed wooden frame and padded seat\", \"url\": \"https://www.target.com/p/-/A-87737798\", \"swatches\": [\"#262522\", \"#8f704a\"], \"imageFallback\": \"https://target.scene7.com/is/image/Target/GUEST_292a0e35-149a-4800-9c5b-da1951cfebbb?fmt=pjpeg&hei=300&wid=300\", \"checkedDate\": \"September 27, 2026\"}, {\"id\": \"target-hairpin-desk\", \"retailer\": \"Target\", \"name\": \"Threshold Hairpin\", \"type\": \"Writing desk\", \"category\": \"desk\", \"price\": 90, \"detail\": \"Brown walnut finish · black metal hairpin legs\", \"caption\": \"a brown walnut finish writing desk with thin black metal hairpin legs and two open storage compartments\", \"url\": \"https://www.target.com/p/hairpin-writing-desk-with-storage-brown-threshold-8482/-/A-86806496\", \"swatches\": [\"#875d3c\", \"#242424\"], \"imageFallback\": \"https://target.scene7.com/is/image/Target/GUEST_d3e75768-5710-4c97-b324-50f830f3dab0?fmt=pjpeg&hei=300&wid=300\", \"checkedDate\": \"September 27, 2026\"}]);\nconst verifiedPhotos={\"article-sven-sofa\": \"https://cdn-images.article.com/products/SKU23884/2890x1500/image175551.jpg?fit=max&w=640\", \"castlery-harper-lift\": \"https://res.cloudinary.com/castlery/image/private/w_1995%2Cf_auto%2Cq_auto%2Cb_rgb%3AF3F3F3%2Cc_fit/v1727315960/crusader/variants/40550262/Harper-Lift-Top-Coffee-Table-Chestnut-Front-1727315958.jpg\", \"castlery-harper-marble\": \"https://res.cloudinary.com/castlery/image/private/w_1995%2Cf_auto%2Cq_auto%2Cb_rgb%3AF3F3F3%2Cc_fit/v1741595640/crusader/variants/40550279/Harper-Marble-Rectangular-Coffee-Table_-_Chestnut-Square-Set_2-1741595638.jpg\"};\nfor (const product of catalog) { product.imageFallback ??= verifiedPhotos[product.id]; product.retailer ??= \"IKEA\"; product.checkedDate ??= \"September 25, 2026\"; product.image = \"/api/product-photo?id=\" + encodeURIComponent(product.id); }\nexport const retailers = [...new Set(catalog.map(p=>p.retailer))];\nexport function filterMatches(scores, {budget, category, retailer='all'}) {\n if(!Number.isFinite(budget)||budget<10||budget>20000) return [];\n const best=Math.max(0,...scores.map(s=>s.score));\n return scores.filter(s=>Number.isFinite(s.score)&&s.score>=best*.18).map(s=>({product:catalog.find(p=>p.caption===s.label),score:s.score})).filter(s=>s.product&&s.product.price<=budget&&(category==='all'||s.product.category===category)&&(retailer==='all'||s.product.retailer===retailer)).sort((a,b)=>b.score-a.score).slice(0,6);\n}\n"},"/matcher-worker.js":{"type":"text/javascript; charset=utf-8","body":"// Run vision inference off the UI thread. Only model files are downloaded;\n// the user's photo is never sent to a server.\nlet classifier;\nconst irrelevant=['a person taking a selfie','a dog or cat','food on a plate','an outdoor landscape','a car or vehicle','a document or text screenshot'];\nconst furniture=['a living room with furniture','a bedroom with a bed and furniture','a home office with a desk','a sofa','an armchair','a coffee table','a bed frame','a desk','a shelving unit','an area rug','a floor lamp'];\nself.onmessage=async({data})=>{\n try {\n  if(!classifier){\n   self.postMessage({type:'status',text:'Downloading image matching. First use can take a minute…'});\n   const {pipeline,env}=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.8.1/dist/transformers.min.js');\n   env.allowLocalModels=false;\n   env.backends.onnx.wasm.numThreads=1;\n   classifier=await pipeline('zero-shot-image-classification','Xenova/clip-vit-base-patch32',{device:'wasm',dtype:'q8',progress_callback:p=>{\n    if(p.status==='progress'&&Number.isFinite(p.progress))self.postMessage({type:'progress',value:p.progress,text:'Downloading image matching files… '+Math.round(p.progress)+'% of current file'});\n   }});\n  }\n  self.postMessage({type:'status',text:'Reading the shapes, materials and colors in your photo…'});\n  const combined=new Map();let count=0;\n  for(const image of data.images||[data.image]){\n   const kind=await classifier(image,[...furniture,...irrelevant]);\n   if(irrelevant.includes(kind[0].label))continue;\n   self.postMessage({type:'status',text:'Comparing inspiration '+(count+1)+' with furniture listings…'});\n   const result=await classifier(image,data.labels);\n   for(const s of result)combined.set(s.label,(combined.get(s.label)||0)+s.score);\n   count++;\n  }\n  if(!count){self.postMessage({type:'unrecognized'});return;}\n  const scores=[...combined].map(([label,score])=>({label,score:score/count})).sort((a,b)=>b.score-a.score);\n  self.postMessage({type:'result',scores});\n } catch(error){\n  classifier=null;\n  self.postMessage({type:'error',message:'Photo matching could not load. Check your internet connection and try again in an up-to-date Chrome, Edge, Firefox or Safari browser.'});\n }\n};\n"},"/room-tools.js":{"type":"text/javascript; charset=utf-8","body":"import {catalog} from './catalog.js';\nexport const cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);\nexport function totalCost(item,tax=0){return Number(item.price||0)*(1+Number(tax||0)/100)+Number(item.delivery||0)+Number(item.assembly||0);}\nexport function fitCheck(item,space){const dims=[item.width,item.depth,item.height].map(Number);if(dims.some(n=>!Number.isFinite(n)||n<=0))return 'Add all three item dimensions';const [w,d]=[space.width,space.depth].map(Number);if(!w||!d)return 'Add room dimensions';const footprint=(dims[0]<=w&&dims[1]<=d)||(dims[1]<=w&&dims[0]<=d);if(!footprint)return 'Footprint exceeds room dimensions';if(Number(space.door)>0&&Math.min(...dims)>Number(space.door))return 'Access warning: smallest item side exceeds opening';return 'Footprint fits; check clearance, packaging and turning space';}\nexport function validateBoard(b){return b&&Array.isArray(b.items)&&b.items.length<=100&&b.items.every(i=>i&&typeof i.id==='string'&&typeof i.name==='string'&&i.name.length<300&&['price','delivery','assembly','width','depth','height','resale','requiredDepth'].every(k=>i[k]==null||i[k]===''||Number.isFinite(Number(i[k]))&&Number(i[k])>=0)&&(!i.contributions||Object.values(i.contributions).every(n=>Number.isFinite(Number(n))&&Number(n)>=0)))&&Array.isArray(b.people)&&b.people.length>0&&b.people.length<=12&&b.people.every(n=>typeof n==='string'&&n.length<=100&&!['__proto__','constructor','prototype'].includes(n))&&Number.isFinite(Number(b.budget))&&Number(b.budget)>=0&&Number.isFinite(Number(b.tax))&&Number(b.tax)>=0&&Number(b.tax)<=30;}\n\nconst $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst key='roomedit-board-v2';let state={items:[],people:['Me'],budget:2500,tax:0,space:{},purpose:'living',horizon:'long'};try{const saved=JSON.parse(localStorage.getItem(key));if(validateBoard(saved))state={...state,...saved};}catch{}\nfunction persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{status('This browser could not save your board. Export a copy.');}}\nfunction status(t){$('#board-status').textContent=t;}\nconst nav=document.querySelector('.mode-tabs');nav.insertAdjacentHTML('beforeend','<button type=\"button\" id=\"board-tab\" aria-pressed=\"false\">Room board &amp; move plan</button>');\nconst section=document.createElement('section');section.id='board-mode';section.hidden=true;document.querySelector('footer').before(section);\n\nconst lanes={\n letgo:{title:'Let go',blurb:'Sell, donate or recycle what isn’t coming with you.',add:'Add something to let go',preset:{source:'owned',decision:'sell'},empty:'Nothing here yet. Add the pieces you’d rather not move: that old couch, the wobbly shelf.'},\n keep:{title:'Bring with me',blurb:'What you own and are moving. Check it fits the new room and the door.',add:'Add something you’re keeping',preset:{source:'owned',decision:'keep'},empty:'List the furniture you’re keeping so you can check it fits through the door and into the new room.'},\n buy:{title:'Get new',blurb:'New and secondhand pieces you’re considering, against your budget.',add:'Add a new piece',preset:{source:'new',decision:'buy'},empty:'Save finds from Shop a photo or Marketplace, add a link you found, or start from a budget starter set.'}\n};\nconst decisionLabels={keep:'Keep',sell:'Sell',donate:'Donate',dispose:'Recycle / dispose',buy:'Buy'};\nconst sourceLabels={owned:'Owned',new:'New',used:'Secondhand'};\nconst icons={sofa:'M3 12v6h18v-6M5 12V8.5A2.5 2.5 0 0 1 7.5 6h9A2.5 2.5 0 0 1 19 8.5V12M3 12a2 2 0 0 1 4 0v2h10v-2a2 2 0 0 1 4 0M6 18v2M18 18v2',chair:'M7 3.5h10V12H7zM5.5 12h13v3.5h-13zM7 15.5V21M17 15.5V21',table:'M3 9h18M6 9v11M18 9v11M4 9l2-3h12l2 3',desk:'M3 8h18M5 8v12M19 8v12M12.5 8v6H19',bed:'M3 19V6M3 14h18v5M21 19v-5M7 14v-3h5v3M12 11h7a2 2 0 0 1 2 2v1',storage:'M4 4h16v16H4zM4 12h16M10 8h4M10 16h4',rug:'M5 5h14v14H5zM8 5V3M12 5V3M16 5V3M8 21v-2M12 21v-2M16 21v-2',lamp:'M8 3h8l3.5 7h-15zM12 10v9M8 21h8',other:'M5 5h14v14H5z'};\nconst laneOf=i=>['sell','donate','dispose'].includes(i.decision)?'letgo':i.decision==='keep'||i.source==='owned'?'keep':'buy';\nconst isSpend=i=>laneOf(i)==='buy';\nconst unknownCost=v=>v===''||v==null;\nconst fitState=msg=>/^Footprint fits/.test(msg)?'ok':/exceeds|warning/i.test(msg)?'warn':'unknown';\nconst shortDate=d=>{if(!d)return '';const t=new Date(d+'T00:00:00Z');return Number.isNaN(+t)?esc(d):t.toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});};\nconst icon=c=>`<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"${icons[c]||icons.other}\"/></svg>`;\nlet view='all';\n\nsection.innerHTML=`<div class=\"rb-hero\"><p class=\"eyebrow\">MOVE-OUT · MOVE-IN · SHOPPING</p><h1>Your move, piece by piece.</h1><p class=\"intro\">Decide what to let go, check what’s coming with you, and plan what’s new, all in one place.</p></div>\n<div id=\"board-overview\" class=\"rb-overview\"></div>\n<div class=\"rb-toolbar\"><div class=\"rb-tabs\" role=\"tablist\" aria-label=\"Board view\">${[['all','Everything'],['letgo','Let go'],['keep','Bring with me'],['buy','Get new']].map(([v,l])=>`<button type=\"button\" role=\"tab\" data-view=\"${v}\" aria-selected=\"${v==='all'}\">${l}<span class=\"rb-count\" data-count=\"${v}\"></span></button>`).join('')}</div>\n<div class=\"rb-toolbar-actions\"><details class=\"rb-menu\"><summary>Share &amp; backup</summary><div class=\"rb-menu-list\"><button type=\"button\" id=\"share-board\">Copy snapshot link</button><button type=\"button\" id=\"export-board\">Download backup (.json)</button><label class=\"import-label\">Restore from backup<input id=\"import-board\" type=\"file\" accept=\"application/json\" hidden></label></div></details><button type=\"button\" class=\"rb-add\" id=\"add-item\">+ Add piece</button></div></div>\n<p id=\"board-status\" class=\"rb-status\" role=\"status\" aria-live=\"polite\"></p>\n<div class=\"board-layout\"><div id=\"board-items\" class=\"rb-lanes\"></div>\n<aside class=\"rb-setup\" aria-labelledby=\"rb-setup-title\"><h2 id=\"rb-setup-title\">Your setup</h2><p class=\"note rb-autosave\">Changes save automatically on this device.</p>\n<details open><summary>Budget</summary><label>What’s the room for?<select id=\"purpose\"><option value=\"living\">Relaxing &amp; hosting</option><option value=\"work\">Working from home</option><option value=\"sleep\">Sleeping</option><option value=\"small\">Small-space living</option></select></label><div class=\"rb-pair\"><label>Budget $<input id=\"room-budget\" type=\"number\" min=\"0\" max=\"1000000\" inputmode=\"decimal\"></label><label>Sales tax %<input id=\"tax-rate\" type=\"number\" min=\"0\" max=\"30\" step=\".01\" inputmode=\"decimal\"></label></div><label>How long will you stay?<select id=\"horizon\"><option value=\"long\">Long-term home</option><option value=\"short\">Under a year / moving often</option></select></label></details>\n<details open><summary>New room &amp; access</summary><div class=\"rb-pair\"><label>Width (in)<input id=\"room-width\" type=\"number\" min=\"1\" inputmode=\"decimal\"></label><label>Depth (in)<input id=\"room-depth\" type=\"number\" min=\"1\" inputmode=\"decimal\"></label></div><label>Narrowest door or elevator (in)<input id=\"room-door\" type=\"number\" min=\"1\" inputmode=\"decimal\"></label><label>Access notes<textarea id=\"access\" placeholder=\"3rd-floor walk-up, elevator booking, tight stair turn…\" maxlength=\"1000\"></textarea></label></details>\n<details><summary>Household</summary><label>Who’s deciding? (comma separated)<input id=\"people\" maxlength=\"200\" placeholder=\"Me, Sam\"></label><p class=\"note\">Add roommates or a partner to record votes and who’s chipping in on new pieces. Shared links are snapshots, not live editing.</p></details>\n<details class=\"rb-tips\"><summary>Before you buy, sell or move</summary><p>Confirm availability and condition in person and agree on pickup timing. A saved listing is not a verified seller or a booking.</p><p>Check curbside vs. in-room delivery, stair fees, elevator rules and return costs with the retailer.</p><p>Measure doors, stair turns and elevators before moving day. Book donation pickups early because they fill up near month-end.</p></details>\n</aside></div>\n<dialog id=\"item-dialog\" class=\"rb-dialog\"><form id=\"item-form\" data-source=\"new\"><div class=\"rb-dialog-head\"><h2 id=\"item-title\">Add a piece</h2><button type=\"button\" class=\"rb-x\" id=\"close-item\" aria-label=\"Close\">×</button></div>\n<fieldset class=\"rb-source\"><legend>What kind of piece?</legend>${Object.entries({owned:'Something I own',new:'New from a store',used:'Secondhand find'}).map(([v,l])=>`<label><input type=\"radio\" name=\"source\" value=\"${v}\"><span>${l}</span></label>`).join('')}</fieldset>\n<div class=\"edit-grid\"><label class=\"wide\">Name<input name=\"name\" required maxlength=\"200\" placeholder=\"e.g. Grey sectional sofa\"></label><label>Category<select name=\"category\">${['sofa','chair','table','desk','bed','storage','rug','lamp','other'].map(v=>`<option value=\"${v}\">${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label>\n<label class=\"only-owned\">Plan for it<select name=\"decision\"><option value=\"keep\">Keep &amp; move it</option><option value=\"sell\">Sell</option><option value=\"donate\">Donate</option><option value=\"dispose\">Recycle / dispose</option></select></label>\n<label class=\"only-buy\">Price $<input name=\"price\" type=\"number\" min=\"0\" max=\"1000000\" step=\".01\" inputmode=\"decimal\"></label></div>\n<h3 class=\"rb-group only-letgo\">Letting it go</h3><div class=\"edit-grid only-letgo\"><label class=\"only-sell\">Expected resale $<input name=\"resale\" type=\"number\" min=\"0\" max=\"1000000\" step=\".01\" inputmode=\"decimal\"></label><label>Gone by<input name=\"deadline\" type=\"date\"></label><label class=\"wide\">Who keeps the money / item?<input name=\"ownership\" maxlength=\"500\" placeholder=\"Split 50/50 with Sam, or Sam buys out my half\"></label></div>\n<h3 class=\"rb-group only-buy\">Cost &amp; buying</h3><div class=\"edit-grid only-buy\"><label class=\"wide\">Link<input name=\"url\" type=\"url\" placeholder=\"https://…\"></label><label>Delivery $<input name=\"delivery\" type=\"number\" min=\"0\" max=\"100000\" step=\".01\" inputmode=\"decimal\" placeholder=\"Unknown\"></label><label>Assembly $<input name=\"assembly\" type=\"number\" min=\"0\" max=\"100000\" step=\".01\" inputmode=\"decimal\" placeholder=\"Unknown\"></label><label class=\"wide\">Style / color notes<input name=\"style\" maxlength=\"300\" placeholder=\"Tan leather, mid-century\"></label></div>\n<h3 class=\"rb-group\">Size</h3><div class=\"edit-grid rb-dims\"><label>Width (in)<input name=\"width\" type=\"number\" min=\".1\" step=\".1\" inputmode=\"decimal\"></label><label>Depth (in)<input name=\"depth\" type=\"number\" min=\".1\" step=\".1\" inputmode=\"decimal\"></label><label>Height (in)<input name=\"height\" type=\"number\" min=\".1\" step=\".1\" inputmode=\"decimal\"></label></div><label class=\"rb-check\"><input name=\"portable\" type=\"checkbox\"> Comes apart or fits in a car (confirmed)</label>\n<details class=\"rb-more\"><summary>More details</summary><div class=\"edit-grid\"><label class=\"only-buy\">Delivery service / timing<input name=\"service\" placeholder=\"In-room, stair fees, delivery date…\" maxlength=\"400\"></label><label class=\"only-buy\">Assembly time / tools<input name=\"tools\" placeholder=\"2 hours, screwdriver\" maxlength=\"300\"></label><label class=\"only-buy\">Returns / payment<input name=\"returns\" maxlength=\"500\" placeholder=\"Return window, fees, payment methods\"></label><label class=\"only-buy\">Availability last checked<input name=\"confirmed\" type=\"date\"></label><label class=\"only-buy\">Proposed pickup<input name=\"pickup\" type=\"datetime-local\"></label><label class=\"only-buy\">Min. desk depth needed (in)<input name=\"requiredDepth\" type=\"number\" min=\".1\" step=\".1\"></label><label class=\"wide\">Condition notes<input name=\"evidence\" maxlength=\"500\" placeholder=\"Receipt, maker marks, wear; your notes, not verified\"></label></div></details>\n<p class=\"note only-buy\">Blank delivery or assembly costs count as unknown, not free.</p>\n<div class=\"rb-dialog-actions\"><button type=\"button\" class=\"rb-btn\" id=\"cancel-item\">Cancel</button><button type=\"submit\" class=\"primary\">Save piece</button></div></form></dialog>`;\n\nfunction switchBoard(){for(const m of ['photo','planner','board']){$('#'+m+'-mode').hidden=m!=='board';$('#'+m+'-tab').setAttribute('aria-pressed',String(m==='board'));}render();}\n$('#board-tab').onclick=switchBoard;for(const m of ['photo','planner'])$('#'+m+'-tab').addEventListener('click',()=>{$('#board-mode').hidden=true;$('#board-tab').setAttribute('aria-pressed','false');});\n\nfunction fillBrief(){for(const [id,value] of Object.entries({'purpose':state.purpose,'horizon':state.horizon,'room-budget':state.budget,'tax-rate':state.tax,'people':state.people.join(', '),'room-width':state.space.width||'','room-depth':state.space.depth||'','room-door':state.space.door||'','access':state.space.access||''}))$('#'+id).value=value;}\nfunction applyBrief(e){if(e&&!e.target.reportValidity())return;if(![...section.querySelectorAll('.rb-setup input')].every(el=>el.checkValidity()))return;state.purpose=$('#purpose').value;state.horizon=$('#horizon').value;state.budget=Number($('#room-budget').value);state.tax=Number($('#tax-rate').value);state.people=[...new Set($('#people').value.split(',').map(n=>n.trim()).filter(n=>n&&n.length<=100&&!['__proto__','constructor','prototype'].includes(n)))].slice(0,12);if(!state.people.length)state.people=['Me'];state.space={width:$('#room-width').value,depth:$('#room-depth').value,door:$('#room-door').value,access:$('#access').value};persist();render();}\nsection.querySelector('.rb-setup').addEventListener('change',applyBrief);\n\nlet editId=null;\nfunction syncForm(){const f=$('#item-form'),source=f.elements.source.value||'new';f.dataset.source=source;const decision=source==='owned'?f.elements.decision.value:'buy';f.dataset.decision=decision;f.dataset.lane=['sell','donate','dispose'].includes(decision)?'letgo':source==='owned'?'keep':'buy';f.elements.price.required=source!=='owned';}\nfunction edit(item,preset){editId=item?.id||null;const f=$('#item-form');f.reset();const data=item||{...preset};for(const el of f.elements){if(!el.name||el.type==='radio')continue;if(el.type==='checkbox')el.checked=!!data[el.name];else el.value=data[el.name]??(el.tagName==='SELECT'?el.options[0].value:'');}\n const source=data.source||'new';f.querySelector(`[name=source][value=\"${source}\"]`).checked=true;if(source==='owned'&&!['keep','sell','donate','dispose'].includes(data.decision))f.elements.decision.value='keep';\n $('#item-title').textContent=item?'Edit piece':preset?.source==='owned'?(preset.decision==='keep'?'Add something you’re keeping':'Add something to let go'):'Add a new piece';syncForm();$('#item-dialog').showModal();f.elements.name.focus();}\n$('#item-form').addEventListener('change',e=>{if(['source','decision'].includes(e.target.name))syncForm();});\n$('#add-item').onclick=()=>edit(null,view==='all'?lanes.buy.preset:lanes[view].preset);$('#cancel-item').onclick=$('#close-item').onclick=()=>$('#item-dialog').close();\n$('#item-dialog').addEventListener('click',e=>{if(e.target.id==='item-dialog')e.target.close();});\n$('#item-form').onsubmit=e=>{e.preventDefault();const f=e.target;const data=Object.fromEntries(new FormData(f));if(data.url&&!/^https?:\\/\\//i.test(data.url)){f.elements.url.setCustomValidity('Use an http or https link.');f.elements.url.reportValidity();f.elements.url.setCustomValidity('');return;}\n if(data.source!=='owned')data.decision='buy';else if(data.price==='')data.price='0';\n const old=state.items.find(i=>i.id===editId);const item={...old,...data,id:editId||crypto.randomUUID(),portable:f.elements.portable.checked};if(old)state.items[state.items.indexOf(old)]=item;else state.items.push(item);persist();render();$('#item-dialog').close();status(`${old?'Updated':'Added'} “${item.name}” in ${lanes[laneOf(item)].title}.`);};\n\nfunction safeUrl(u){try{const url=new URL(u);return ['http:','https:'].includes(url.protocol)?url.href:'';}catch{return '';}}\n\nfunction overview(){const by=l=>state.items.filter(i=>laneOf(i)===l),go=by('letgo'),keep=by('keep'),buy=by('buy');\n const spend=buy.reduce((s,i)=>s+totalCost(i,state.tax),0),pct=state.budget>0?Math.min(100,spend/state.budget*100):spend>0?100:0,over=spend>state.budget;\n const resale=go.filter(i=>i.decision==='sell').reduce((s,i)=>s+Number(i.resale||0),0);\n const next=go.map(i=>i.deadline).filter(Boolean).sort()[0];\n const warn=keep.filter(i=>fitState(fitCheck(i,state.space))==='warn').length,bulky=keep.filter(i=>!i.portable).length;\n const unknown=buy.filter(i=>unknownCost(i.delivery)||unknownCost(i.assembly)).length;\n const n=(c,w)=>`${c} ${c===1?w:w+'s'}`;\n $('#board-overview').innerHTML=`<button type=\"button\" class=\"rb-stat rb-stat-letgo\" data-view=\"letgo\"><span class=\"rb-stat-label\">Let go</span><strong>${n(go.length,'piece')}</strong><span>${resale?cash(resale)+' expected from sales':go.length?'Nothing listed for sale':'Sell, donate or recycle'}${next?` · first due ${shortDate(next)}`:''}</span></button>\n <button type=\"button\" class=\"rb-stat rb-stat-keep\" data-view=\"keep\"><span class=\"rb-stat-label\">Bring with me</span><strong>${n(keep.length,'piece')}</strong><span>${keep.length?(warn?`<b class=\"rb-warn-text\">${n(warn,'fit warning')}</b> · `:'')+`${bulky} need${bulky===1?'s':''} a truck or helpers`:'Check fit before moving day'}</span></button>\n <button type=\"button\" class=\"rb-stat rb-stat-buy\" data-view=\"buy\"><span class=\"rb-stat-label\">Get new</span><strong>${cash(spend)} <small>of ${cash(state.budget)}</small></strong><span class=\"rb-meter${over?' is-over':''}\" role=\"img\" aria-label=\"${Math.round(spend/(state.budget||1)*100)}% of budget\"><span style=\"width:${pct}%\"></span></span><span>${over?`<b class=\"rb-warn-text\">${cash(spend-state.budget)} over budget</b>`:cash(state.budget-spend)+' left'}${unknown?` · ${unknown} with unknown delivery/assembly`:''}</span></button>`;\n for(const l of ['all','letgo','keep','buy'])section.querySelector(`[data-count=\"${l}\"]`).textContent=l==='all'?state.items.length||'':by(l).length||'';}\n\nfunction card(i){const lane=laneOf(i),fit=fitCheck(i,state.space),fs=fitState(fit),total=totalCost(i,state.tax),multi=state.people.length>1,id=esc(i.id);\n const dims=[i.width,i.depth,i.height].every(v=>Number(v)>0)?`${esc(i.width)}″ W × ${esc(i.depth)}″ D × ${esc(i.height)}″ H`:'Size not added';\n const fitChip=`<span class=\"rb-chip rb-fit-${fs}\" title=\"${esc(fit)}\">${fs==='ok'?'✓ Fits':fs==='warn'?'⚠ '+(/Access/.test(fit)?'Door check':'Too big'):'Fit unknown'}</span>`;\n const votes=Object.entries(i.votes||{}).filter(([p,v])=>state.people.includes(p)&&v!=='Undecided');const yes=votes.filter(([,v])=>v==='Yes').length;\n let detail='',side='';\n if(lane==='letgo'){side=i.decision==='sell'?`<strong class=\"rb-amount\">${cash(Number(i.resale||0))}</strong><span class=\"rb-sub\">expected</span>`:'';\n  detail=`<p class=\"rb-line\">${i.deadline?`Gone by <b>${shortDate(i.deadline)}</b>`:'No deadline set'}${i.ownership?' · '+esc(i.ownership):''}</p>`;}\n else if(lane==='keep'){detail=`<p class=\"rb-line\">${dims} · ${i.portable?'Comes apart / car-friendly':'Needs a truck or helpers'}</p>${fs==='warn'?`<p class=\"rb-alert\">${esc(fit)}</p>`:''}`;}\n else{side=`<strong class=\"rb-amount\">${cash(total)}</strong><span class=\"rb-sub\">est. total</span>`;\n  detail=`<p class=\"rb-line\">${cash(Number(i.price||0))} + ${cash(Number(i.price||0)*state.tax/100)} tax · delivery ${unknownCost(i.delivery)?'<em>unknown</em>':cash(Number(i.delivery))} · assembly ${unknownCost(i.assembly)?'<em>unknown</em>':cash(Number(i.assembly))}</p>${fs==='warn'?`<p class=\"rb-alert\">${esc(fit)}</p>`:''}${Number(i.requiredDepth)>0?`<p class=\"rb-line\">Desk depth: ${!Number(i.depth)?'unknown':Number(i.depth)>=Number(i.requiredDepth)?'meets your minimum':'<b class=\"rb-warn-text\">too shallow for your need</b>'}</p>`:''}`;}\n const contributed=Object.entries(i.contributions||{}).filter(([p])=>state.people.includes(p)).reduce((s,[,n])=>s+Number(n||0),0);\n const household=lane==='buy'&&multi?`<details class=\"rb-household\"><summary>Household · ${votes.length}/${state.people.length} voted${votes.length?`, ${yes} yes`:''}${contributed?` · ${cash(contributed)} pledged`:''}</summary><div class=\"household\">${state.people.map((name,index)=>`<div class=\"rb-person\"><span>${esc(name)}</span><select aria-label=\"${esc(name)}’s vote on ${esc(i.name)}\" data-vote=\"${id}\" data-person=\"${index}\">${['Undecided','Yes','Maybe','No'].map(v=>`<option ${i.votes?.[name]===v?'selected':''}>${v}</option>`).join('')}</select><input aria-label=\"${esc(name)} contribution for ${esc(i.name)}\" placeholder=\"$ chipping in\" type=\"number\" min=\"0\" step=\".01\" data-contribution=\"${id}\" data-person=\"${index}\" value=\"${esc(i.contributions?.[name]||'')}\"></div>`).join('')}</div><p class=\"note\">${contributed>total?'Overfunded by '+cash(contributed-total):cash(Math.max(0,total-contributed))+' still unfunded'}. Records only; no payments are processed.</p></details>`:'';\n const facts=[['Size',dims],['Fit',esc(fit)],...(lane==='buy'?[['Delivery',esc(i.service||'Not checked')],['Assembly',esc(i.tools||'Not checked')],['Returns',esc(i.returns||'Not checked')],['Availability',i.confirmed?'Checked '+shortDate(i.confirmed):'Not confirmed'],['Pickup',esc(i.pickup||'Not arranged')]]:[]),['Condition',esc(i.evidence||'No notes')],...(lane!=='buy'&&i.ownership?[['Ownership',esc(i.ownership)]]:[])];\n const decide=i.source==='owned'?`<label class=\"rb-decide\"><span class=\"visually-hidden\">Plan for ${esc(i.name)}</span><select data-decision=\"${id}\">${['keep','sell','donate','dispose'].map(d=>`<option value=\"${d}\" ${i.decision===d||(d==='keep'&&lane==='keep')?'selected':''}>${decisionLabels[d]}</option>`).join('')}</select></label>`:'';\n return `<article class=\"rb-item rb-item-${lane}\"><div class=\"rb-icon\">${icon(i.category)}</div><div class=\"rb-main\"><div class=\"rb-head\"><h3>${esc(i.name)}</h3><div class=\"rb-side\">${side}</div></div>\n <div class=\"rb-chips\"><span class=\"rb-chip\">${sourceLabels[i.source]||'New'}</span>${lane==='letgo'?`<span class=\"rb-chip rb-chip-${esc(i.decision)}\">${decisionLabels[i.decision]}</span>`:''}${lane!=='letgo'?fitChip:''}${i.portable?'<span class=\"rb-chip\">Portable</span>':''}${i.style&&lane==='buy'?`<span class=\"rb-style\">${esc(i.style)}</span>`:''}</div>\n ${detail}${household}\n <div class=\"rb-actions\">${decide}<details class=\"rb-facts\"><summary>Details</summary><dl>${facts.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></details>${safeUrl(i.url)?`<a href=\"${esc(safeUrl(i.url))}\" target=\"_blank\" rel=\"noopener noreferrer\">Open listing ↗</a>`:''}<button type=\"button\" data-edit=\"${id}\">Edit</button><button type=\"button\" class=\"rb-remove\" data-delete=\"${id}\" aria-label=\"Remove ${esc(i.name)}\">Remove</button></div></div></article>`;}\n\nfunction render(){overview();for(const b of section.querySelectorAll('.rb-tabs [data-view]'))b.setAttribute('aria-selected',String(b.dataset.view===view));\n const order=view==='all'?['letgo','keep','buy']:[view];\n $('#board-items').innerHTML=!state.items.length&&view==='all'?`<div class=\"rb-start\"><h2>Start with what you have.</h2><p>Moving, downsizing or refreshing a room? Sort each piece into one of three piles:</p><div class=\"rb-start-grid\">${Object.entries(lanes).map(([l,x])=>`<button type=\"button\" class=\"rb-start-card rb-stat-${l}\" data-add=\"${l}\"><strong>${x.title}</strong><span>${x.blurb}</span><b>${x.add} →</b></button>`).join('')}</div></div>`:\n order.map(l=>{let items=state.items.filter(i=>laneOf(i)===l);if(state.horizon==='short'&&l!=='letgo')items=[...items].sort((a,b)=>Number(b.portable)-Number(a.portable));const x=lanes[l];\n  return `<section class=\"rb-lane rb-lane-${l}\" aria-labelledby=\"lane-${l}\"><div class=\"rb-lane-head\"><div><h2 id=\"lane-${l}\">${x.title} <span>${items.length||''}</span></h2><p>${x.blurb}</p></div><div class=\"rb-lane-actions\">${l==='buy'?'<button type=\"button\" class=\"rb-btn\" id=\"starter\">Budget starter set</button>':''}<button type=\"button\" class=\"rb-btn\" data-add=\"${l}\">+ Add</button></div></div>${items.length?items.map(card).join(''):`<p class=\"rb-empty\">${x.empty}</p>`}</section>`;}).join('');}\n\nsection.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!section.contains(b))return;\n if(b.dataset.view){view=b.dataset.view;render();if(b.classList.contains('rb-stat'))$('#board-items').scrollIntoView({behavior:'smooth',block:'start'});return;}\n if(b.dataset.add)return edit(null,lanes[b.dataset.add].preset);\n if(b.id==='starter')return starter();\n if(b.dataset.edit)return edit(state.items.find(i=>i.id===b.dataset.edit));\n if(b.dataset.delete){const item=state.items.find(i=>i.id===b.dataset.delete);if(!item)return;state.items=state.items.filter(i=>i!==item);persist();render();status(`Removed “${item.name}”.`);}});\n$('#board-items').addEventListener('change',e=>{const el=e.target;\n if(el.dataset.decision){const item=state.items.find(i=>i.id===el.dataset.decision);if(!item)return;item.decision=el.value;persist();render();status(`“${item.name}” moved to ${lanes[laneOf(item)].title}.`);return;}\n const id=el.dataset.vote||el.dataset.contribution;if(!id)return;const item=state.items.find(i=>i.id===id),person=state.people[Number(el.dataset.person)];if(!item||!person||!el.reportValidity())return;if(el.dataset.vote){item.votes??={};item.votes[person]=el.value;}else{item.contributions??={};item.contributions[person]=Number(el.value);}persist();const open=el.closest('details')?.open;render();if(open)section.querySelector(`[data-vote=\"${CSS.escape(id)}\"]`)?.closest('details')?.setAttribute('open','');});\n\nfunction saveProduct(p){if(state.items.some(i=>i.catalogId===p.id)){status('That piece is already on your board.');return false;}state.items.push({id:crypto.randomUUID(),catalogId:p.id,name:p.name+' '+p.type,price:p.price,url:p.url,style:p.detail,category:p.category,source:'new',decision:'buy',delivery:'',assembly:''});persist();render();return true;}\nwindow.addEventListener('roomedit-save',e=>{const p=catalog.find(p=>p.id===e.detail);if(p&&saveProduct(p))status('Saved '+p.name+' to Get new on your room board.');});\nfunction starter(){const groups={living:['sofa','table','lamp'],work:['desk','chair','lamp'],sleep:['bed','table','lamp'],small:['chair','storage','lamp']}[state.purpose];let remaining=Math.max(0,state.budget-state.items.filter(isSpend).reduce((s,i)=>s+totalCost(i,state.tax),0));let count=0;for(const cat of groups){if(state.items.some(i=>i.category===cat&&laneOf(i)!=='letgo'))continue;const p=catalog.filter(p=>p.category===cat&&!state.items.some(i=>i.catalogId===p.id)).sort((a,b)=>a.price-b.price)[0];if(p&&p.price*(1+state.tax/100)<=remaining){saveProduct(p);remaining-=p.price*(1+state.tax/100);count++;}}status(count?`Added ${count} low-cost starter ${count===1?'piece':'pieces'}, skipping categories you already own or plan to buy. Check delivery and assembly costs.`:'No starter pieces fit your remaining budget, or you already have every category covered.');}\n$('#export-board').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='roomedit-board.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);section.querySelector('.rb-menu').open=false;status('Backup downloaded.');};\nfunction importBoard(b){if(!validateBoard(b))throw Error();state={...state,...b,space:b.space||{}};persist();fillBrief();render();switchBoard();}\n$('#import-board').onchange=async e=>{section.querySelector('.rb-menu').open=false;try{const file=e.target.files[0];if(!file||file.size>500000)throw Error();const b=JSON.parse(await file.text());if(state.items.length&&!confirm('Replace your current board with this backup?'))return;importBoard(b);status('Board restored from backup.');}catch{status('Could not restore this file. Choose a Room Edit .json backup under 500 KB.');}e.target.value='';};\n$('#share-board').onclick=async()=>{section.querySelector('.rb-menu').open=false;const data=btoa(unescape(encodeURIComponent(JSON.stringify(state))));if(data.length>16000){status('This board is too large for a link. Download a backup instead.');return;}const url=location.origin+location.pathname+'#board='+data;try{await navigator.clipboard.writeText(url);status('Snapshot link copied. It includes names, contributions and notes; changes won’t sync.');}catch{status('Clipboard unavailable. Download a backup to share instead.');}};\nfillBrief();render();if(location.hash.startsWith('#board=')){try{const b=JSON.parse(decodeURIComponent(escape(atob(location.hash.slice(7)))));if(validateBoard(b)&&confirm('Load the shared board snapshot? This replaces your local board.'))importBoard(b);}catch{status('The shared board link could not be read.');}history.replaceState(null,'',location.pathname);}\n\nwindow.addEventListener('roomedit-market-save',e=>{const p=e.detail;if(state.items.some(i=>i.marketId===p.id)){status('This marketplace piece is already on your board.');return;}state.items.push({id:crypto.randomUUID(),marketId:p.id,name:p.name+' (demo listing)',price:p.price,source:'used',decision:'buy',category:p.category,width:p.width,depth:p.depth,height:p.height,portable:p.portable,delivery:'',assembly:'',evidence:p.condition+' · Demo seller: '+p.seller+' · Not verified',service:p.platform+' · '+p.area+' · Pickup preference: '+(p.pickupPreference||'not selected')+' (not booked)',style:'Marketplace demo'});persist();render();status('Marketplace piece saved to Get new. Pickup is a preference, not a booking.');});\n"},"/room-tools.css":{"type":"text/css; charset=utf-8","body":"#board-mode{--rb-go:#b5703d;--rb-go-soft:#f6ebe0;--rb-keep:#4f6fae;--rb-keep-soft:#e7edf7;--rb-buy:var(--green);--rb-buy-soft:#e6eee3;--rb-muted:#667067;--rb-warn:#a5492a}\n.mode-tabs{flex-wrap:wrap}\n.rb-hero{margin-bottom:26px}.rb-hero .intro{margin:0;max-width:620px}\n.rb-overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:26px}\n.rb-stat{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:6px;background:#fff;border:1px solid var(--line);border-top:4px solid var(--c);border-radius:10px;padding:18px 20px;transition:box-shadow .2s,transform .2s}\n.rb-stat:hover{box-shadow:0 10px 26px #232b2612;transform:translateY(-1px)}\n.rb-stat:focus-visible{outline:3px solid #8d9bb5;outline-offset:2px}\n.rb-stat-letgo{--c:var(--rb-go);--s:var(--rb-go-soft)}.rb-stat-keep{--c:var(--rb-keep);--s:var(--rb-keep-soft)}.rb-stat-buy{--c:var(--rb-buy);--s:var(--rb-buy-soft)}\n.rb-stat-label{font-size:11px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:var(--c)}\n.rb-stat strong{font-size:24px;font-weight:700;letter-spacing:-.5px}.rb-stat strong small{font-size:14px;font-weight:400;color:var(--rb-muted);letter-spacing:0}\n.rb-stat>span:last-child{font-size:13px;color:var(--rb-muted);line-height:1.45}\n.rb-warn-text{color:var(--rb-warn)}\n.rb-meter{display:block;height:7px;border-radius:9px;background:#e8ebe3;overflow:hidden;margin:2px 0}.rb-meter span{display:block;height:100%;background:var(--green);border-radius:9px}.rb-meter.is-over span{background:var(--rb-warn)}\n.rb-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;border-bottom:1px solid var(--line);margin-bottom:6px}\n.rb-tabs{display:flex;gap:2px;overflow-x:auto}\n.rb-tabs button{background:none;border:0;border-bottom:3px solid transparent;padding:11px 14px;color:var(--rb-muted);font-size:15px;white-space:nowrap}\n.rb-tabs button[aria-selected=true]{border-color:var(--ink);color:var(--ink);font-weight:700}\n.rb-count{display:inline-block;margin-left:7px;font-size:12px;background:#eceee8;border-radius:9px;padding:1px 7px;font-weight:700;color:#556055}.rb-count:empty{display:none}\n.rb-toolbar-actions{display:flex;gap:8px;align-items:center;padding-bottom:8px}\n.rb-add{background:var(--green);color:#fff;border:0;border-radius:6px;padding:10px 16px;font-weight:700}.rb-add:hover{background:#234731}\n.rb-menu{position:relative}\n.rb-menu summary{list-style:none;border:1px solid var(--line);background:#fff;border-radius:6px;padding:9px 14px;font-size:14px}.rb-menu summary::-webkit-details-marker{display:none}.rb-menu summary::after{content:' ▾';color:var(--rb-muted)}\n.rb-menu-list{position:absolute;right:0;top:calc(100% + 6px);z-index:5;background:#fff;border:1px solid var(--line);border-radius:8px;box-shadow:0 14px 34px #232b261f;padding:6px;min-width:230px;display:grid}\n.rb-menu-list button,.rb-menu-list label{all:unset;box-sizing:border-box;cursor:pointer;padding:10px 12px;border-radius:5px;font-size:14px}.rb-menu-list button:hover,.rb-menu-list label:hover,.rb-menu-list button:focus-visible{background:var(--paper)}\n.rb-menu-list label:focus-within{outline:3px solid #8d9bb5}\n.rb-status{min-height:20px;margin:8px 0 10px;font-size:14px;color:var(--green)}\n.board-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:30px;align-items:start}\n.rb-setup{position:sticky;top:20px;background:#fff;border:1px solid var(--line);border-radius:10px;padding:20px}\n.rb-setup h2{font-family:Georgia,serif;font-size:22px;font-weight:400;margin:0}.rb-autosave{margin:4px 0 12px}\n.rb-setup details{border-top:1px solid var(--line);padding:12px 0 4px}.rb-setup summary{font-size:12px;font-weight:700;letter-spacing:1.3px;text-transform:uppercase;color:#4f5a4f;padding-bottom:6px}\n.rb-setup label{display:block;font-size:13px;margin:8px 0 12px;color:#3f4a40}\n.rb-setup input,.rb-setup select,.rb-setup textarea,.edit-grid input,.edit-grid select{display:block;width:100%;padding:9px 10px;border:1px solid #ccd3c9;border-radius:6px;margin-top:5px;background:#fff;font:inherit;font-size:15px;box-sizing:border-box;color:var(--ink)}\n.rb-setup textarea{min-height:64px;resize:vertical}\n.rb-pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.rb-tips p{font-size:13px;line-height:1.55;color:var(--rb-muted);margin:0 0 9px}\n.rb-lanes{display:grid;gap:26px}\n.rb-lane-head{display:flex;justify-content:space-between;align-items:flex-end;gap:14px;margin-bottom:10px}\n.rb-lane-head h2{font-family:Georgia,serif;font-size:26px;font-weight:400;margin:0;display:flex;align-items:center;gap:10px}\n.rb-lane-head h2::before{content:'';width:10px;height:10px;border-radius:50%;background:var(--c)}\n.rb-lane-head h2 span{font:700 13px Arial,sans-serif;color:var(--rb-muted)}\n.rb-lane-head p{margin:4px 0 0;font-size:14px;color:var(--rb-muted)}\n.rb-lane-letgo{--c:var(--rb-go);--s:var(--rb-go-soft)}.rb-lane-keep{--c:var(--rb-keep);--s:var(--rb-keep-soft)}.rb-lane-buy{--c:var(--rb-buy);--s:var(--rb-buy-soft)}\n.rb-lane-actions{display:flex;gap:8px;flex:none}\n.rb-btn{border:1px solid var(--line);background:#fff;border-radius:6px;padding:8px 13px;font-size:14px;font-weight:700;color:var(--ink)}.rb-btn:hover{border-color:#a9b3a3;background:var(--paper)}\n.rb-empty{margin:0;border:1.5px dashed #cfd5ca;border-radius:10px;padding:22px;font-size:14px;color:var(--rb-muted);line-height:1.55;background:#fafaf7}\n.rb-item{display:grid;grid-template-columns:46px minmax(0,1fr);gap:16px;background:#fff;border:1px solid var(--line);border-left:4px solid var(--c);border-radius:10px;padding:16px 18px;margin-bottom:10px}\n.rb-icon{width:46px;height:46px;border-radius:10px;background:var(--s);display:grid;place-items:center}.rb-icon svg{width:26px;height:26px;fill:none;stroke:var(--c);stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}\n.rb-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}\n.rb-head h3{font-family:Georgia,serif;font-size:21px;font-weight:400;margin:2px 0 6px;line-height:1.25;overflow-wrap:anywhere}\n.rb-side{text-align:right;flex:none;display:flex;flex-direction:column}.rb-amount{font-size:20px;letter-spacing:-.3px}.rb-sub{font-size:11px;color:var(--rb-muted);text-transform:uppercase;letter-spacing:1px}\n.rb-chips{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-bottom:8px}\n.rb-chip{font-size:12px;font-weight:700;border-radius:999px;padding:3px 9px;background:#eff1ec;color:#4c574c}\n.rb-chip-sell{background:var(--rb-go-soft);color:#8a4f22}.rb-chip-donate{background:#f3e9f0;color:#7a3d66}.rb-chip-dispose{background:#ececec;color:#555}\n.rb-fit-ok{background:#e4efe3;color:#2f6a3e}.rb-fit-warn{background:#f8e6df;color:var(--rb-warn)}.rb-fit-unknown{background:#f1f1ed;color:#7a8078}\n.rb-style{font-size:13px;color:var(--rb-muted)}\n.rb-line{margin:0 0 6px;font-size:14px;color:#4f5a4f;line-height:1.5}.rb-line em{color:#8a5a2b;font-style:normal}\n.rb-alert{margin:0 0 6px;font-size:13px;color:var(--rb-warn);background:#fbf0eb;border-radius:6px;padding:7px 10px}\n.rb-actions{display:flex;flex-wrap:wrap;gap:4px 14px;align-items:center;margin-top:8px}\n.rb-actions>button,.rb-actions>a,.rb-facts summary{background:none;border:0;padding:4px 0;font-size:14px;color:var(--green);text-decoration:underline;text-underline-offset:3px;font-weight:400}\n.rb-actions .rb-remove{color:#8a3b2a}\n.rb-decide select{width:auto;padding:6px 9px;border:1px solid var(--line);border-radius:6px;background:var(--s);font-size:14px;font-weight:700;color:var(--ink)}\n.rb-facts{order:10;flex-basis:100%}.rb-facts:not([open]){flex-basis:auto;order:0}.rb-facts summary{list-style:none;cursor:pointer}.rb-facts summary::-webkit-details-marker{display:none}.rb-facts[open] summary::after{content:' ▴'}.rb-facts:not([open]) summary::after{content:' ▾'}\n.rb-facts dl{margin:8px 0 0;background:var(--paper);border-radius:8px;padding:6px 14px}.rb-facts dl div{display:grid;grid-template-columns:110px 1fr;gap:12px;padding:7px 0;border-bottom:1px solid #e5e6df;font-size:13px}.rb-facts dl div:last-child{border:0}.rb-facts dt{color:var(--rb-muted)}.rb-facts dd{margin:0}\n.rb-household{margin:6px 0 2px;background:var(--paper);border-radius:8px;padding:9px 12px}.rb-household summary{font-size:13px;font-weight:700;color:#4f5a4f}\n.household{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:10px;margin-top:10px}\n.rb-person{display:grid;gap:5px;font-size:13px;font-weight:700}.rb-person select,.rb-person input{width:100%;padding:7px 8px;border:1px solid var(--line);border-radius:5px;font:inherit;font-weight:400;background:#fff;box-sizing:border-box}\n.rb-household .note{margin-top:8px}\n.rb-start{background:#fff;border:1px solid var(--line);border-radius:12px;padding:32px}\n.rb-start h2{font-family:Georgia,serif;font-size:32px;font-weight:400;margin:0 0 6px}.rb-start>p{color:var(--rb-muted);margin:0 0 20px}\n.rb-start-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n.rb-start-card{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:8px;background:var(--s);border-radius:10px;padding:18px;border-top:4px solid var(--c)}\n.rb-start-card strong{font-size:18px}.rb-start-card span{font-size:14px;line-height:1.5;color:#4f5a4f;flex:1}.rb-start-card b{font-size:13px;color:var(--c)}\n.rb-start-card:hover{filter:brightness(.98)}.rb-start-card:focus-visible{outline:3px solid #8d9bb5;outline-offset:2px}\n.rb-dialog{border:0;border-radius:14px;max-width:680px;width:calc(100vw - 32px);max-height:calc(100vh - 32px);overflow:auto;padding:0;box-shadow:0 30px 80px #0004;color:var(--ink)}\n.rb-dialog::backdrop{background:#1d241fa6}\n.rb-dialog form{padding:24px 26px}\n.rb-dialog-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.rb-dialog-head h2{font-family:Georgia,serif;font-size:27px;font-weight:400}\n.rb-x{width:36px;height:36px;border-radius:50%;border:0;background:#f0f1ec;font-size:22px;line-height:1}\n.rb-source{border:0;padding:0;margin:0 0 6px;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.rb-source legend,.rb-group{font-size:12px;font-weight:700;letter-spacing:1.3px;text-transform:uppercase;color:#4f5a4f;padding:0;margin:0 0 8px}\n.rb-group{margin:18px 0 0;padding-top:16px;border-top:1px solid var(--line)}\n.rb-source label{position:relative}.rb-source input{position:absolute;opacity:0}\n.rb-source span{display:block;text-align:center;border:1px solid var(--line);border-radius:8px;padding:11px 8px;font-size:14px;cursor:pointer}\n.rb-source input:checked+span{border-color:var(--green);background:#eaf0e9;color:var(--green);font-weight:700}.rb-source input:focus-visible+span{outline:3px solid #8d9bb5;outline-offset:2px}\n.edit-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.edit-grid label{display:block;font-size:13px;margin:12px 0 0;color:#3f4a40}.edit-grid .wide{grid-column:1/-1}\n.rb-dims{grid-template-columns:repeat(3,1fr)}\n.rb-check{display:flex;gap:9px;align-items:center;font-size:14px;margin:14px 0 0}.rb-check input{width:16px;height:16px}\n.rb-more{margin-top:18px;border-top:1px solid var(--line);padding-top:12px}.rb-more summary{font-size:14px;font-weight:700;color:var(--green)}\n.rb-dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px;position:sticky;bottom:-24px;background:#fff;padding:12px 0 2px}.rb-dialog-actions .primary{width:auto;padding:12px 22px}.rb-dialog-actions .rb-btn{padding:12px 18px}\n#item-form:not([data-source=owned]) .only-owned,#item-form[data-source=owned] .only-buy,#item-form:not([data-lane=letgo]) .only-letgo,#item-form:not([data-decision=sell]) .only-sell{display:none}\n@media(max-width:1000px){.board-layout{grid-template-columns:1fr}.rb-setup{position:static}}\n@media(max-width:760px){.rb-overview{grid-template-columns:1fr;gap:8px}.rb-stat{padding:14px 16px}.rb-stat strong{font-size:20px}.rb-start-grid{grid-template-columns:1fr}.rb-start{padding:22px}\n .rb-toolbar{flex-direction:column;align-items:stretch;gap:0}.rb-toolbar-actions{justify-content:space-between;padding:10px 0}.rb-tabs button{padding:10px 10px;font-size:14px}\n .rb-item{grid-template-columns:1fr;gap:8px;padding:14px}.rb-icon{display:none}.rb-head h3{font-size:19px}\n .rb-lane-head{flex-direction:column;align-items:flex-start}.rb-lane-head h2{font-size:23px}\n .rb-source{grid-template-columns:1fr}.edit-grid{grid-template-columns:1fr}.rb-dims{grid-template-columns:repeat(3,1fr);gap:0 8px}.rb-dialog form{padding:20px}}\n@media(prefers-reduced-motion:reduce){.rb-stat{transition:none}.rb-stat:hover{transform:none}}\n"},"/marketplace.js":{"type":"text/javascript; charset=utf-8","body":"const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);\nconst categories=[['all','All'],['sofa','Sofas'],['chair','Chairs'],['table','Tables'],['desk','Desks'],['storage','Storage'],['lamp','Lighting']];\nconst platforms=[['all','All sources'],['Facebook Marketplace','Facebook Marketplace'],['OfferUp','OfferUp'],['Craigslist','Craigslist']];\nconst sorts=[['recent','Newest first'],['price-asc','Price: low to high'],['price-desc','Price: high to low'],['nearest','Nearest first'],['savings','Biggest savings']];\nconst defaults={q:'',category:'all',platform:'all',budget:'1000',distance:'10',available:true,portable:false,sort:'recent'};\nconst chips=(name,list)=>list.map(([value,label],i)=>`<label class=\"mk-chip\"><input type=\"radio\" name=\"${name}\" value=\"${escape(value)}\"${i?'':' checked'}><span>${escape(label)}</span></label>`).join('');\n\ndocument.querySelector('.mode-tabs').insertAdjacentHTML('beforeend','<button type=\"button\" id=\"market-tab\" aria-pressed=\"false\">Marketplace</button>');\nconst section=document.createElement('section');section.id='market-mode';section.hidden=true;document.querySelector('footer').before(section);\nsection.innerHTML=`<div class=\"mk-hero\"><div><p class=\"eyebrow\">SECONDHAND &amp; UNIQUE FINDS</p><h1>Good pieces. A second chapter.</h1><p class=\"intro\">Browse pre-loved furniture near Austin, compare what you'd save against buying new, and send favorites to your room board.</p></div><p class=\"mk-disclosure\"><b>Demo listings</b> Sample inventory in the style of Facebook Marketplace, OfferUp and Craigslist feeds. Listings and sellers are fictional.</p></div>\n<div class=\"mk-layout\"><aside class=\"mk-filters\" id=\"market-filter-panel\"><form id=\"market-filters\" novalidate>\n<label class=\"mk-search\"><span class=\"visually-hidden\">Search listings</span><svg viewBox=\"0 0 20 20\" aria-hidden=\"true\"><circle cx=\"8.5\" cy=\"8.5\" r=\"5.5\"/><path d=\"m13 13 4.5 4.5\"/></svg><input name=\"q\" type=\"search\" placeholder=\"Walnut, lamp, Zilker…\" maxlength=\"100\" autocomplete=\"off\"></label>\n<fieldset><legend>Category</legend><div class=\"mk-chips\">${chips('category',categories)}</div></fieldset>\n<fieldset><legend>Source</legend><div class=\"mk-chips mk-chips-stack\">${chips('platform',platforms)}</div></fieldset>\n<div class=\"mk-range\"><label for=\"market-budget\">Max price</label><output id=\"market-budget-out\" for=\"market-budget\">$1,000</output><input id=\"market-budget\" name=\"budget\" type=\"range\" min=\"50\" max=\"1000\" step=\"25\" value=\"1000\"></div>\n<div class=\"mk-range\"><label for=\"market-distance\">Distance</label><output id=\"market-distance-out\" for=\"market-distance\">Within 10 mi</output><input id=\"market-distance\" name=\"distance\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"10\"></div>\n<fieldset class=\"mk-toggles\"><legend class=\"visually-hidden\">Options</legend><label><input name=\"available\" type=\"checkbox\" checked> Available now</label><label><input name=\"portable\" type=\"checkbox\"> Fits in a car or disassembles</label></fieldset>\n<button type=\"button\" class=\"mk-reset\" id=\"market-reset\">Reset filters</button>\n</form></aside>\n<div class=\"mk-main\"><div class=\"mk-toolbar\"><button type=\"button\" class=\"mk-filter-toggle\" id=\"market-filter-toggle\" aria-controls=\"market-filter-panel\" aria-expanded=\"false\">Filters</button><p id=\"market-status\" role=\"status\" aria-live=\"polite\"></p><label class=\"mk-sort\">Sort<select name=\"sort\" form=\"market-filters\">${sorts.map(([v,l])=>`<option value=\"${v}\">${l}</option>`).join('')}</select></label></div>\n<div id=\"market-active\" class=\"mk-active\"></div><div id=\"market-results\" class=\"mk-grid\" aria-busy=\"false\"></div></div></div>\n<dialog id=\"market-dialog\" class=\"mk-dialog\" aria-labelledby=\"market-dialog-title\"><div id=\"market-dialog-body\"></div></dialog>`;\n\nconst form=$('#market-filters'),results=$('#market-results'),status=$('#market-status'),dialog=$('#market-dialog');\nlet listings=[],loaded=false,controller,timer;const saved=new Set();\n\nfor(const m of ['photo','planner','board'])$('#'+m+'-tab')?.addEventListener('click',()=>{section.hidden=true;$('#market-tab').setAttribute('aria-pressed','false');});\n$('#market-tab').onclick=()=>{for(const m of ['photo','planner','board']){const mode=$('#'+m+'-mode'),tab=$('#'+m+'-tab');if(mode)mode.hidden=true;tab?.setAttribute('aria-pressed','false');}section.hidden=false;$('#market-tab').setAttribute('aria-pressed','true');if(!loaded)search();};\n\nfunction artwork(p){const c=escape(p.color);let shape=p.shape==='lamp'?`<path d=\"M155 62h50l18 48h-86z\" fill=\"${c}\"/><path d=\"M180 110v90m-32 0h64\" stroke=\"${c}\" stroke-width=\"8\"/>`:p.shape==='table'?`<ellipse cx=\"180\" cy=\"115\" rx=\"100\" ry=\"27\" fill=\"${c}\"/><path d=\"M180 125v75m-45 0h90\" stroke=\"${c}\" stroke-width=\"14\"/>`:p.shape==='sofa'||p.shape==='chair'?`<rect x=\"${p.shape==='chair'?115:65}\" y=\"80\" width=\"${p.shape==='chair'?130:230}\" height=\"100\" rx=\"18\" fill=\"${c}\"/><rect x=\"${p.shape==='chair'?100:50}\" y=\"120\" width=\"30\" height=\"65\" rx=\"10\" fill=\"${c}\"/><rect x=\"${p.shape==='chair'?230:280}\" y=\"120\" width=\"30\" height=\"65\" rx=\"10\" fill=\"${c}\"/><path d=\"M130 180v20m100-20v20\" stroke=\"#67513f\" stroke-width=\"7\"/>`:`<rect x=\"65\" y=\"95\" width=\"230\" height=\"${p.shape==='desk'?18:80}\" rx=\"4\" fill=\"${c}\"/><path d=\"M80 113v85m200-85v85\" stroke=\"${c}\" stroke-width=\"9\"/>`;return `<svg viewBox=\"0 25 360 205\" role=\"img\" aria-label=\"Illustration of ${escape(p.name)}\"><rect y=\"25\" width=\"360\" height=\"205\" fill=\"#ece9df\"/><ellipse cx=\"180\" cy=\"207\" rx=\"125\" ry=\"13\" fill=\"#d8d3c6\"/>${shape}</svg>`;}\nconst savings=p=>p.retail>p.price?Math.round((1-p.price/p.retail)*100):0;\nconst ago=d=>d===0?'Listed today':d===1?'Listed yesterday':`Listed ${d} days ago`;\nconst dot=platform=>`<span class=\"mk-dot\" data-platform=\"${escape(platform)}\"></span>`;\n\nfunction card(p){const off=savings(p),available=p.status==='Available',isSaved=saved.has(p.id);\n return `<article class=\"mk-card${available?'':' is-pending'}\"><button type=\"button\" class=\"mk-art\" data-market-open=\"${escape(p.id)}\" aria-label=\"View details for ${escape(p.name)}\">${artwork(p)}<span class=\"mk-badge mk-badge-source\">${dot(p.platform)}${escape(p.platform)}</span>${!available?'<span class=\"mk-badge mk-badge-status\">Pending</span>':p.posted===0?'<span class=\"mk-badge mk-badge-new\">New today</span>':''}<span class=\"mk-art-note\">Illustration</span></button>\n <div class=\"mk-body\"><div class=\"mk-price-row\"><strong>${money(p.price)}</strong>${off?`<span class=\"mk-save-pill\">${off}% below new</span>`:''}</div><h3><button type=\"button\" class=\"mk-title\" data-market-open=\"${escape(p.id)}\">${escape(p.name)}</button></h3><p class=\"mk-meta\">${escape(p.area.replace(', Austin',''))} · ${p.distance} mi · ${ago(p.posted)}</p><p class=\"mk-cond\">${escape(p.condition)}</p><p class=\"mk-dims\">${p.width}″ W × ${p.depth}″ D × ${p.height}″ H${p.portable?' · <span>Portable</span>':''}</p>\n <div class=\"mk-actions\"><button type=\"button\" class=\"mk-btn\" data-market-open=\"${escape(p.id)}\">Details &amp; pickup</button><button type=\"button\" class=\"mk-btn mk-btn-primary\" data-market-save=\"${escape(p.id)}\" ${!available||isSaved?'disabled':''}>${isSaved?'Saved ✓':available?'Save':'Unavailable'}</button></div></div></article>`;}\n\nfunction activeChips(){const data=new FormData(form),out=[];\n const add=(key,label)=>out.push(`<button type=\"button\" class=\"mk-pill\" data-clear=\"${key}\">${escape(label)}<span aria-hidden=\"true\">×</span><span class=\"visually-hidden\"> remove filter</span></button>`);\n if(data.get('q').trim())add('q',`“${data.get('q').trim()}”`);if(data.get('category')!=='all')add('category',categories.find(c=>c[0]===data.get('category'))[1]);if(data.get('platform')!=='all')add('platform',data.get('platform'));if(data.get('budget')!==defaults.budget)add('budget','Under '+money(Number(data.get('budget'))));if(data.get('distance')!==defaults.distance)add('distance','Within '+data.get('distance')+' mi');if(!form.elements.available.checked)add('available','Including pending');if(form.elements.portable.checked)add('portable','Portable only');\n $('#market-active').innerHTML=out.length?out.join('')+'<button type=\"button\" class=\"mk-clear-all\" data-clear=\"all\">Clear all</button>':'';\n $('#market-filter-toggle').textContent=out.length?`Filters (${out.length})`:'Filters';}\n\nfunction syncOutputs(){$('#market-budget-out').textContent=Number(form.elements.budget.value)>=1000?'$1,000+':money(Number(form.elements.budget.value));const d=form.elements.distance.value;$('#market-distance-out').textContent=d==='10'?'Within 10 mi':`Within ${d} mi`;}\n\nasync function search(){controller?.abort();controller=new AbortController();const current=controller;syncOutputs();activeChips();\n const params=new URLSearchParams(new FormData(form));for(const name of ['available','portable'])params.set(name,form.elements[name].checked?'true':'false');if(params.get('budget')==='1000')params.set('budget','');\n results.setAttribute('aria-busy','true');if(!loaded){results.innerHTML=Array.from({length:6},()=>'<div class=\"mk-card mk-skeleton\" aria-hidden=\"true\"><div></div><p></p><p></p></div>').join('');status.textContent='Finding pieces…';}else results.classList.add('is-loading');\n try{const response=await fetch('/api/marketplace?'+params,{signal:current.signal});if(!response.ok)throw Error();const data=await response.json();if(current!==controller)return;listings=data.listings;loaded=true;\n  status.innerHTML=listings.length?`<b>${listings.length}</b> ${listings.length===1?'piece':'pieces'} near central Austin`:'No matches';\n  results.innerHTML=listings.length?listings.map(card).join(''):'<div class=\"mk-empty\"><h2>Nothing matches yet.</h2><p>Try a broader search, another source or a higher price limit. New pieces are listed every day.</p><button type=\"button\" class=\"mk-btn\" data-clear=\"all\">Clear all filters</button></div>';\n }catch(e){if(e.name!=='AbortError'){status.textContent='The marketplace feed could not load.';results.innerHTML='<div class=\"mk-empty\"><h2>We couldn’t load listings.</h2><p>Check your connection and try again.</p><button type=\"button\" class=\"mk-btn\" id=\"market-retry\">Try again</button></div>';}}\n finally{if(current===controller){results.setAttribute('aria-busy','false');results.classList.remove('is-loading');}}}\n\nfunction save(p,pickupPreference=''){if(!p||p.status!=='Available'||saved.has(p.id))return;window.dispatchEvent(new CustomEvent('roomedit-market-save',{detail:{...p,pickupPreference}}));saved.add(p.id);\n for(const b of document.querySelectorAll(`[data-market-save=\"${CSS.escape(p.id)}\"]`)){b.textContent='Saved ✓';b.disabled=true;}\n status.innerHTML=`<b>${escape(p.name)}</b> saved. Open <button type=\"button\" class=\"mk-link\" id=\"market-to-board\">Room board &amp; move plan</button> to compare costs and fit.`;}\n\nfunction openDetails(p){const off=savings(p),available=p.status==='Available',isSaved=saved.has(p.id);\n $('#market-dialog-body').innerHTML=`<button type=\"button\" class=\"mk-close\" data-close aria-label=\"Close\">×</button><div class=\"mk-dialog-grid\"><div class=\"mk-dialog-art\">${artwork(p)}<p class=\"mk-art-caption\">Illustration · ask the seller for current photos</p></div><div class=\"mk-dialog-info\"><p class=\"eyebrow\">${dot(p.platform)}${escape(p.platform)} · ${escape(p.status)}</p><h2 id=\"market-dialog-title\">${escape(p.name)}</h2><div class=\"mk-price-row\"><strong>${money(p.price)}</strong>${off?`<span class=\"mk-save-pill\">Save about ${money(p.retail-p.price)} vs. ~${money(p.retail)} new</span>`:''}</div>\n <dl class=\"mk-facts\"><div><dt>Condition</dt><dd>${escape(p.condition)}</dd></div><div><dt>Location</dt><dd>${escape(p.area)} · ${p.distance} mi</dd></div><div><dt>Size</dt><dd>${p.width}″ W × ${p.depth}″ D × ${p.height}″ H</dd></div><div><dt>Moving</dt><dd>${p.portable?'Portable or disassembles':'Needs a truck or van and two people'}</dd></div><div><dt>Seller</dt><dd>${escape(p.seller)} · identity not verified</dd></div><div><dt>Listed</dt><dd>${ago(p.posted)}</dd></div></dl>\n ${available?`<fieldset class=\"mk-slots\"><legend>Proposed pickup window</legend>${p.slots.map((s,i)=>`<label><input type=\"radio\" name=\"pickup\" value=\"${escape(s)}\"${i?'':''}> ${escape(s)}</label>`).join('')}<label><input type=\"radio\" name=\"pickup\" value=\"\" checked> Decide later</label></fieldset>`:'<p class=\"mk-pending-note\">Another buyer has a pending pickup. Check back later.</p>'}\n <button type=\"button\" class=\"primary\" data-dialog-save=\"${escape(p.id)}\" ${!available||isSaved?'disabled':''}>${isSaved?'Saved to room board ✓':available?'Save to room board':'Pending · unavailable'}</button><p class=\"note\">Saving a pickup preference doesn’t book anything. Meet in a public or well-lit place, check the piece in person and pay only after you’ve seen it.</p></div></div>`;\n dialog.showModal();}\n\nform.addEventListener('submit',e=>{e.preventDefault();search();});\nform.addEventListener('input',e=>{syncOutputs();clearTimeout(timer);timer=setTimeout(search,e.target.name==='q'?250:120);});\n$('#market-reset').onclick=()=>reset();\nfunction reset(key='all'){if(key==='all'||key==='q')form.elements.q.value='';for(const k of ['category','platform'])if(key==='all'||key===k)form.querySelector(`[name=${k}][value=\"all\"]`).checked=true;if(key==='all'||key==='budget')form.elements.budget.value=defaults.budget;if(key==='all'||key==='distance')form.elements.distance.value=defaults.distance;if(key==='all'||key==='available')form.elements.available.checked=true;if(key==='all'||key==='portable')form.elements.portable.checked=false;search();}\n$('#market-filter-toggle').onclick=e=>{const panel=$('#market-filter-panel'),open=!panel.classList.contains('is-open');panel.classList.toggle('is-open',open);e.currentTarget.setAttribute('aria-expanded',String(open));};\nsection.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;\n if(t.dataset.clear)return reset(t.dataset.clear);\n if(t.id==='market-retry')return search();\n if(t.id==='market-to-board')return $('#board-tab')?.click();\n if(t.dataset.marketOpen)return openDetails(listings.find(p=>p.id===t.dataset.marketOpen));\n if(t.dataset.marketSave)return save(listings.find(p=>p.id===t.dataset.marketSave));\n if(t.dataset.dialogSave){const p=listings.find(p=>p.id===t.dataset.dialogSave);save(p,dialog.querySelector('[name=pickup]:checked')?.value||'');t.textContent='Saved to room board ✓';t.disabled=true;return;}\n if('close' in t.dataset)dialog.close();});\ndialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});\n"},"/marketplace.css":{"type":"text/css; charset=utf-8","body":".visually-hidden{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n#market-mode{--mk-muted:#667067;--mk-soft:#eef1ea;--mk-accent:#b5703d}\n.mk-hero{display:grid;grid-template-columns:1fr minmax(240px,340px);gap:32px;align-items:end;margin-bottom:30px}\n.mk-hero .intro{margin:0;max-width:560px}\n.mk-disclosure{margin:0;font-size:12px;line-height:1.55;color:#5c6a57;background:#e7eddf;border-radius:8px;padding:12px 14px}\n.mk-disclosure b{display:block;font-size:11px;letter-spacing:1.4px;text-transform:uppercase;margin-bottom:3px;color:var(--green)}\n.mk-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:36px;align-items:start}\n.mk-filters{position:sticky;top:20px;background:#fff;border:1px solid var(--line);border-radius:10px;padding:20px}\n.mk-filters fieldset{border:0;padding:0;margin:0 0 22px;min-width:0}\n.mk-filters legend,.mk-range label{font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:#4f5a4f;margin-bottom:10px;padding:0}\n.mk-search{display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:999px;padding:0 14px;margin-bottom:22px;background:var(--paper)}\n.mk-search:focus-within{border-color:var(--green);box-shadow:0 0 0 3px #315a4226}\n.mk-search svg{width:17px;height:17px;flex:none;fill:none;stroke:#7a837a;stroke-width:2;stroke-linecap:round}\n.mk-search input{border:0;background:none;padding:11px 0;width:100%;min-width:0;outline:0;color:var(--ink)}\n.mk-chips{display:flex;flex-wrap:wrap;gap:6px}\n.mk-chips-stack{flex-direction:column;align-items:stretch}\n.mk-chip{position:relative}\n.mk-chip input{position:absolute;opacity:0;inset:0}\n.mk-chip span{display:block;border:1px solid var(--line);border-radius:999px;padding:7px 12px;font-size:13px;cursor:pointer;background:#fff;transition:background .15s,border-color .15s}\n.mk-chips-stack .mk-chip span{border-radius:6px}\n.mk-chip span:hover{border-color:#a9b3a3}\n.mk-chip input:checked+span{background:var(--green);border-color:var(--green);color:#fff}\n.mk-chip input:focus-visible+span{outline:3px solid #8d9bb5;outline-offset:2px}\n.mk-range{display:grid;grid-template-columns:1fr auto;align-items:baseline;margin-bottom:20px}\n.mk-range output{font-size:13px;color:var(--green);font-weight:700}\n.mk-range input{grid-column:1/-1;margin:4px 0 0;width:100%}\n.mk-toggles label{display:flex;gap:9px;align-items:flex-start;font-size:14px;margin-bottom:10px;line-height:1.35;cursor:pointer}\n.mk-toggles input{margin:2px 0 0;width:16px;height:16px;flex:none}\n.mk-reset{background:none;border:0;padding:0;color:var(--green);font-size:13px;text-decoration:underline;text-underline-offset:3px}\n.mk-toolbar{display:flex;align-items:center;gap:14px;margin-bottom:12px;min-height:42px}\n#market-status{margin:0;flex:1;font-size:14px;color:var(--mk-muted)}\n#market-status b{color:var(--ink)}\n.mk-sort{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--mk-muted);white-space:nowrap}\n.mk-sort select{width:auto;padding:9px 10px;font-size:14px}\n.mk-filter-toggle{display:none}\n.mk-link{background:none;border:0;padding:0;color:var(--green);text-decoration:underline;text-underline-offset:3px;font-size:inherit}\n.mk-active{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}\n.mk-active:empty{display:none}\n.mk-pill{display:inline-flex;gap:7px;align-items:center;background:var(--mk-soft);border:1px solid #d6decf;border-radius:999px;padding:5px 11px;font-size:13px;color:#36503c}\n.mk-pill span[aria-hidden]{font-size:15px;line-height:1;color:#6c7a68}\n.mk-clear-all{background:none;border:0;font-size:13px;color:var(--mk-muted);text-decoration:underline;text-underline-offset:3px}\n.mk-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:18px;transition:opacity .15s}\n.mk-grid.is-loading{opacity:.55}\n.mk-card{background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden;display:flex;flex-direction:column;transition:box-shadow .2s,transform .2s}\n.mk-card:hover{box-shadow:0 10px 28px #232b2614;transform:translateY(-2px)}\n.mk-card.is-pending{opacity:.72}\n.mk-art{position:relative;display:block;border:0;padding:0;background:#ece9df;width:100%;cursor:pointer}\n.mk-art svg,.mk-dialog-art svg{display:block;width:100%;height:auto}\n.mk-art:focus-visible{outline:3px solid var(--green);outline-offset:-3px}\n.mk-badge{position:absolute;top:10px;font-size:11px;font-weight:700;border-radius:999px;padding:5px 9px;display:inline-flex;align-items:center;gap:6px}\n.mk-badge-source{left:10px;background:#ffffffeb;color:#3c473d}\n.mk-badge-new{right:10px;background:var(--green);color:#fff}\n.mk-badge-status{right:10px;background:#5f5a52;color:#fff}\n.mk-art-note{position:absolute;right:10px;bottom:8px;font-size:10px;letter-spacing:1px;text-transform:uppercase;color:#8a8f84}\n.mk-dot{width:8px;height:8px;border-radius:50%;display:inline-block;background:#7b8a77;flex:none}\n.mk-dot[data-platform=\"Facebook Marketplace\"]{background:#4f6fae}\n.mk-dot[data-platform=\"OfferUp\"]{background:#2e9f82}\n.mk-dot[data-platform=\"Craigslist\"]{background:#7a5aa6}\n.eyebrow .mk-dot{margin-right:7px;vertical-align:1px}\n.mk-body{padding:16px 16px 18px;display:flex;flex-direction:column;flex:1}\n.mk-price-row{display:flex;align-items:center;gap:9px;flex-wrap:wrap}\n.mk-price-row strong{font-size:22px;font-weight:700;letter-spacing:-.4px}\n.mk-save-pill{font-size:12px;font-weight:700;color:#8a4f22;background:#f6e9dc;border-radius:999px;padding:3px 9px}\n.mk-body h3{margin:6px 0 4px;font-family:Georgia,serif;font-weight:400;font-size:20px;line-height:1.25}\n.mk-title{all:unset;cursor:pointer}\n.mk-title:hover{text-decoration:underline;text-underline-offset:4px}\n.mk-title:focus-visible{outline:3px solid var(--green);outline-offset:2px}\n.mk-body p{margin:0;font-size:13px;line-height:1.5;color:var(--mk-muted)}\n.mk-cond{margin-top:6px!important;color:#3f4a40!important}\n.mk-dims span{color:var(--green);font-weight:700}\n.mk-actions{display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:auto;padding-top:16px}\n.mk-btn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:6px;padding:10px 14px;font-size:14px;font-weight:700;transition:background .15s,border-color .15s}\n.mk-btn:hover:not(:disabled){border-color:#a9b3a3;background:var(--paper)}\n.mk-btn-primary{background:var(--green);border-color:var(--green);color:#fff;min-width:86px}\n.mk-btn-primary:hover:not(:disabled){background:#234731;border-color:#234731}\n.mk-btn:disabled{cursor:default;background:var(--mk-soft);border-color:var(--mk-soft);color:#6b766a}\n.mk-skeleton{min-height:360px;pointer-events:none}\n.mk-skeleton div{aspect-ratio:360/205;background:#ece9df}\n.mk-skeleton p{height:14px;margin:16px 16px 0;border-radius:4px;background:#eceee8}\n.mk-skeleton p+p{width:50%}\n.mk-empty{grid-column:1/-1;background:#e8eee3;border-radius:10px;padding:46px 36px;text-align:center}\n.mk-empty h2{font-family:Georgia,serif;font-weight:400;font-size:30px;margin:0 0 10px}\n.mk-empty p{color:#57634f;max-width:420px;margin:0 auto 18px;line-height:1.6}\n.mk-dialog{border:0;border-radius:14px;padding:0;width:min(860px,calc(100vw - 32px));max-height:calc(100vh - 32px);color:var(--ink);box-shadow:0 30px 80px #0004}\n.mk-dialog::backdrop{background:#1d241fa6}\n.mk-close{position:absolute;top:10px;right:12px;width:36px;height:36px;border-radius:50%;border:0;background:#fffffff0;font-size:24px;line-height:1;z-index:1}\n.mk-close:hover{background:var(--mk-soft)}\n.mk-dialog-grid{display:grid;grid-template-columns:1fr 1fr}\n.mk-dialog-art{background:#ece9df;display:flex;flex-direction:column;justify-content:center}\n.mk-art-caption{font-size:11px;color:#7d8478;text-align:center;margin:0 0 14px}\n.mk-dialog-info{padding:30px 28px 26px}\n.mk-dialog-info h2{font-family:Georgia,serif;font-size:30px;font-weight:400;letter-spacing:-.5px;margin:0 0 10px}\n.mk-facts{margin:20px 0;display:grid;gap:0;border-top:1px solid var(--line)}\n.mk-facts div{display:grid;grid-template-columns:90px 1fr;gap:12px;padding:9px 0;border-bottom:1px solid var(--line);font-size:14px}\n.mk-facts dt{color:var(--mk-muted)}\n.mk-facts dd{margin:0}\n.mk-slots{border:0;padding:0;margin:0 0 18px}\n.mk-slots legend{font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:#4f5a4f;margin-bottom:8px;padding:0}\n.mk-slots label{display:flex;gap:9px;align-items:center;border:1px solid var(--line);border-radius:6px;padding:10px 12px;font-size:14px;margin-bottom:6px;cursor:pointer}\n.mk-slots label:has(input:checked){border-color:var(--green);background:var(--mk-soft)}\n.mk-pending-note{background:#f1eee8;border-radius:6px;padding:12px;font-size:14px;color:#5f5a52}\n@media(max-width:900px){.mk-hero{grid-template-columns:1fr;gap:16px}.mk-layout{grid-template-columns:1fr;gap:0}\n .mk-filters{display:none;position:static;margin-bottom:16px}.mk-filters.is-open{display:block}\n .mk-filter-toggle{display:inline-flex;border:1px solid var(--line);background:#fff;border-radius:999px;padding:9px 16px;font-size:14px;font-weight:700}\n .mk-chips-stack{flex-direction:row}.mk-chips-stack .mk-chip span{border-radius:999px}}\n@media(max-width:640px){.mk-toolbar{flex-wrap:wrap}#market-status{order:3;flex-basis:100%}.mk-sort{margin-left:auto}\n .mk-grid{grid-template-columns:1fr 1fr;gap:10px}.mk-body{padding:12px}.mk-body h3{font-size:17px}.mk-price-row strong{font-size:19px}.mk-save-pill{font-size:11px;padding:2px 7px}\n .mk-actions{grid-template-columns:1fr}.mk-btn{padding:9px 10px;font-size:13px}.mk-badge-source{font-size:0;padding:5px;gap:0}.mk-art-note{display:none}\n .mk-dialog-grid{grid-template-columns:1fr}.mk-dialog-info{padding:20px}.mk-dialog-info h2{font-size:25px}}\n@media(max-width:380px){.mk-grid{grid-template-columns:1fr}}\n@media(prefers-reduced-motion:reduce){.mk-card,.mk-grid,.mk-chip span{transition:none}.mk-card:hover{transform:none}}\n"}};
